export const BODY = {"level-6":{"id":"level-6","kind":"level","level":6,"src":"level:6","title":"Level 6 · Below Zero","body":"Adding and taking away negative numbers, prime factors, HCF and LCM, square roots, all four sums with fractions, area of triangles, angles in a shape, and the middle of a list.","route":"#/atlas","cta":"See the road"},"land-l6-negatives":{"id":"land-l6-negatives","kind":"land","level":6,"src":"land:l6-negatives","title":"Below zero — in The Deep Mine","body":"6 stops on this stretch of the road: Below zero · Higher or lower? · Riding the lift · How far apart? · Adding a negative · Taking away a negative.","art":"art/w-mine.webp","route":"#/world/mine","cta":"Visit Mine"},"land-l6-factors":{"id":"land-l6-factors","kind":"land","level":6,"src":"land:l6-factors","title":"Prime factors, HCF and LCM — in The Factor Forest","body":"5 stops on this stretch of the road: Tests for 6 and 11 · Factor trees · Highest common factor · Lowest common multiple · Building with prime stones.","art":"art/w-forest.webp","route":"#/world/forest","cta":"Visit Forest"},"land-l6-powers":{"id":"land-l6-powers","kind":"land","level":6,"src":"land:l6-powers","title":"Squares and roots — in The Square Palace","body":"3 stops on this stretch of the road: What a square number is · Every square to 20 · Square roots.","art":"art/w-palace.webp","route":"#/world/palace","cta":"Visit Palace"},"land-l6-fractions":{"id":"land-l6-fractions","kind":"land","level":6,"src":"land:l6-fractions","title":"Fractions with any bottom — in The Fraction Bakery","body":"4 stops on this stretch of the road: Mixed numbers and top-heavy fractions · Adding different-sized slices · Multiplying fractions · Dividing by a fraction.","art":"art/w-bakery.webp","route":"#/world/bakery","cta":"Visit Bakery"},"land-l6-shape":{"id":"land-l6-shape","kind":"land","level":6,"src":"land:l6-shape","title":"Angles and triangles — in Shape City","body":"3 stops on this stretch of the road: Angles on a line and round a point · Angles inside a shape · Triangles and parallelograms.","art":"art/w-shapecity.webp","route":"#/world/shapecity","cta":"Visit Shape City"},"land-l6-data":{"id":"land-l6-data","kind":"land","level":6,"src":"land:l6-data","title":"Mean, median and mode — in The Data Carnival","body":"3 stops on this stretch of the road: The mean: fair shares · Median and mode · The range: how spread out?.","art":"art/w-carnival.webp","route":"#/world/carnival","cta":"Visit Carnival"},"trick-negative-numbers-idea":{"id":"trick-negative-numbers-idea","kind":"trick","src":"stop:negative-numbers#idea","title":"Below zero","body":"On a number line, count to zero first, then carry on past it. A thermometer is a number line standing up. Zero is not the bottom — the numbers keep going down: −1, −2, −3. The further below zero, the colder, so −8 is colder than −3 even though 8 is bigger than 3.","cta":"Learn the trick","level":6,"route":"#/stop/negative-numbers"},"story-negative-numbers-open":{"id":"story-negative-numbers-open","kind":"story","src":"story:negative-numbers#open","badge":{"id":"story","label":"A story"},"title":"The frosty morning","body":"At dawn the garden thermometer reads −3 °C. By lunch it is 8 degrees warmer. — with Nova and Pip.","art":"art/s-garden.webp","cta":"Read the story","level":6,"route":"#/stop/negative-numbers"},"hook-negative-numbers-hook":{"id":"hook-negative-numbers-hook","kind":"hook","src":"stop:negative-numbers#hook","title":"Can you? — Below zero","body":"It is −3 °C and it gets 8 degrees warmer. Is it 11 degrees?","cta":"Find out how","level":6,"route":"#/stop/negative-numbers"},"idea-negative-numbers-case0":{"id":"idea-negative-numbers-case0","kind":"idea","src":"stop:negative-numbers#case0","title":"Below zero: Warmer, past zero","body":"Rising from below zero, the first few degrees only get you back to 0. What is left of the rise takes you above it.","cta":"See it worked","level":6,"route":"#/stop/negative-numbers"},"worked-negative-numbers-worked0":{"id":"worked-negative-numbers-worked0","kind":"worked","src":"stop:negative-numbers#worked0","title":"Worked out — Below zero: Warmer, past zero","body":"It is −3 °C. It gets 8 degrees warmer. What is the temperature now?: From −3 up to 0 → 3 · Degrees still to rise after 0: 8 − 3 → 5 · So the temperature is → 5","cta":"Watch it step by step","level":6,"route":"#/stop/negative-numbers"},"idea-negative-numbers-case1":{"id":"idea-negative-numbers-case1","kind":"idea","src":"stop:negative-numbers#case1","title":"Below zero: Warmer, still below zero","body":"A small rise does not reach zero. It just brings you closer: 9 below, 4 warmer, is 5 below.","cta":"See it worked","level":6,"route":"#/stop/negative-numbers"},"worked-negative-numbers-worked1":{"id":"worked-negative-numbers-worked1","kind":"worked","src":"stop:negative-numbers#worked1","title":"Worked out — Below zero: Warmer, still below zero","body":"It is −9 °C. It gets 4 degrees warmer. What is the temperature now?: −9 is how far below zero? → 9 · Warmer by 4 brings it closer to zero: 9 − 4 → 5 · Still below zero, so it is → -5","cta":"Watch it step by step","level":6,"route":"#/stop/negative-numbers"},"idea-negative-numbers-case2":{"id":"idea-negative-numbers-case2","kind":"idea","src":"stop:negative-numbers#case2","title":"Below zero: Colder, past zero","body":"Falling from above zero, the first degrees take you down to 0. The rest take you below it.","cta":"See it worked","level":6,"route":"#/stop/negative-numbers"},"worked-negative-numbers-worked2":{"id":"worked-negative-numbers-worked2","kind":"worked","src":"stop:negative-numbers#worked2","title":"Worked out — Below zero: Colder, past zero","body":"It is 4 °C. It gets 7 degrees colder. What is the temperature now?: From 4 down to 0 → 4 · Degrees still to fall below 0: 7 − 4 → 3 · Below zero, so it is → -3","cta":"Watch it step by step","level":6,"route":"#/stop/negative-numbers"},"idea-negative-numbers-case3":{"id":"idea-negative-numbers-case3","kind":"idea","src":"stop:negative-numbers#case3","title":"Below zero: Colder, further below","body":"Already below zero? Colder takes you even further below, so the two distances add: 2 below, 5 colder, is 7 below.","cta":"See it worked","level":6,"route":"#/stop/negative-numbers"},"worked-negative-numbers-worked3":{"id":"worked-negative-numbers-worked3","kind":"worked","src":"stop:negative-numbers#worked3","title":"Worked out — Below zero: Colder, further below","body":"It is −2 °C. It gets 5 degrees colder. What is the temperature now?: −2 is how far below zero? → 2 · Colder by 5 takes it further: 2 + 5 → 7 · Below zero, so it is → -7","cta":"Watch it step by step","level":6,"route":"#/stop/negative-numbers"},"idea-negative-numbers-case4":{"id":"idea-negative-numbers-case4","kind":"idea","src":"stop:negative-numbers#case4","title":"Below zero: The gap across zero","body":"Zero sits between the two temperatures, so add the two distances from zero.","cta":"See it worked","level":6,"route":"#/stop/negative-numbers"},"worked-negative-numbers-worked4":{"id":"worked-negative-numbers-worked4","kind":"worked","src":"stop:negative-numbers#worked4","title":"Worked out — Below zero: The gap across zero","body":"The night was −6 °C. The afternoon was 4 °C. How many degrees warmer was the afternoon?: From −6 up to 0 → 6 · From 0 up to 4 → 4 · Add the two jumps → 10","cta":"Watch it step by step","level":6,"route":"#/stop/negative-numbers"},"idea-negative-numbers-case5":{"id":"idea-negative-numbers-case5","kind":"idea","src":"stop:negative-numbers#case5","title":"Below zero: The gap below zero","body":"Both are below zero, so zero is not between them. Take the smaller distance from the bigger one.","cta":"See it worked","level":6,"route":"#/stop/negative-numbers"},"worked-negative-numbers-worked5":{"id":"worked-negative-numbers-worked5","kind":"worked","src":"stop:negative-numbers#worked5","title":"Worked out — Below zero: The gap below zero","body":"The night was −9 °C. The afternoon was −2 °C. How many degrees warmer was the afternoon?: How far is −9 below zero? → 9 · And −2? → 2 · The gap: 9 − 2 → 7","cta":"Watch it step by step","level":6,"route":"#/stop/negative-numbers"},"why-negative-numbers-why1":{"id":"why-negative-numbers-why1","kind":"why","src":"stop:negative-numbers#why1","title":"Why “Below zero” works","body":"Getting warmer means moving up the line. From −3, the first 3 degrees only bring you back to zero; that uses up 3 of the 8. The 5 that are left take you above zero, to 5. Stopping at zero splits one hard jump into two easy ones.","cta":"See why","level":6,"route":"#/stop/negative-numbers"},"why-negative-numbers-why2":{"id":"why-negative-numbers-why2","kind":"why","src":"stop:negative-numbers#why2","title":"Why “Below zero” works","body":"The gap between two temperatures works the same way. From −6 up to 4 is 6 to reach zero and 4 more — 10 degrees. Two distances from zero, added, because zero sits between them.","cta":"See why","level":6,"route":"#/stop/negative-numbers"},"why-negative-numbers-why3":{"id":"why-negative-numbers-why3","kind":"why","src":"stop:negative-numbers#why3","title":"Why “Below zero” works","body":"Getting colder is moving down, and zero is the stop again: from 4, falling 7 uses 4 to reach zero and takes you 3 below, to −3. If you start below zero, colder just goes further below: −2, then 5 colder, is −7. And when both temperatures are below zero, zero is not between them, so the gap is one distance take away the other: −9 to −2 is 7 degrees.","cta":"See why","level":6,"route":"#/stop/negative-numbers"},"algebra-negative-numbers-alg":{"id":"algebra-negative-numbers-alg","kind":"algebra","src":"stop:negative-numbers#alg","title":"The algebra behind “Below zero”","body":"−a + b = b − a ; the gap from −a to b is a + b","cta":"See why","level":6,"route":"#/stop/negative-numbers"},"moment-negative-numbers-beat3":{"id":"moment-negative-numbers-beat3","kind":"moment","src":"story:negative-numbers#beat3","badge":{"id":"story","label":"A story"},"title":"The frosty morning — on the notepad","body":"Nova: That used 3 of the 8. How many are left? 8 − 3 = 5","cta":"Read the story","level":6,"route":"#/stop/negative-numbers"},"moral-negative-numbers-beat5":{"id":"moral-negative-numbers-beat5","kind":"moral","src":"story:negative-numbers#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “The frosty morning”","body":"Get to zero first, then carry on. Zero splits the jump in two.","cta":"Read the story","level":6,"route":"#/stop/negative-numbers"},"try-negative-numbers-L6":{"id":"try-negative-numbers-L6","kind":"try","level":6,"src":"try:negative-numbers@6/1#0","title":"Below zero — your turn","route":"#/stop/negative-numbers","cta":"Practise this stop","play":{"q":"It is 5 °C. It gets 12 degrees colder. What is the temperature now?","opts":["-7","5","7"],"after":"On a number line, count to zero first, then carry on past it."}},"trick-area-triangles-idea":{"id":"trick-area-triangles-idea","kind":"trick","src":"stop:area-triangles#idea","title":"Triangles and parallelograms","body":"A parallelogram is base × height. A triangle is half of that: ½ × base × height. Always the straight-up height, never the slope. Cut the triangle off one sloping end of a parallelogram and slide it to the other end. It fits exactly, and now you have a rectangle — the same base, the same height, and not a scrap of area gained or lost. So a parallelogram's area is base × height, just like the rectangle it became.","cta":"Learn the trick","level":6,"route":"#/stop/area-triangles"},"story-area-triangles-open":{"id":"story-area-triangles-open","kind":"story","src":"story:area-triangles#open","badge":{"id":"story","label":"A story"},"title":"The market awning","body":"A stall awning is a leaning parallelogram: base 9 m, straight-up height 4 m, sloping side 5 m. — with Vesper and Theo.","art":"art/s-market.webp","cta":"Read the story","level":6,"route":"#/stop/area-triangles"},"hook-area-triangles-hook":{"id":"hook-area-triangles-hook","kind":"hook","src":"stop:area-triangles#hook","title":"Can you? — Triangles and parallelograms","body":"A parallelogram leans over. Its base is 9 cm and it stands 4 cm tall. What is its area?","cta":"Find out how","level":6,"route":"#/stop/area-triangles"},"idea-area-triangles-case0":{"id":"idea-area-triangles-case0","kind":"idea","src":"stop:area-triangles#case0","title":"Triangles and parallelograms: A parallelogram","body":"Slide the sloping end across and it becomes a rectangle, so its area is base × the straight-up height.","cta":"See it worked","level":6,"route":"#/stop/area-triangles"},"worked-area-triangles-worked0":{"id":"worked-area-triangles-worked0","kind":"worked","src":"stop:area-triangles#worked0","title":"Worked out — Triangles and parallelograms: A parallelogram","body":"A parallelogram has a base of 9 cm and a height of 4 cm. What is its area, in cm²?: Slide the end triangle across: a rectangle this wide → 9 · and this tall (straight up, not the slope) → 4 · 9 × 4 → 36","cta":"Watch it step by step","level":6,"route":"#/stop/area-triangles"},"idea-area-triangles-case1":{"id":"idea-area-triangles-case1","kind":"idea","src":"stop:area-triangles#case1","title":"Triangles and parallelograms: Ignore the slope","body":"The sloping side is given too, but it is a trap: only the straight-up height tells you how tall the shape stands.","cta":"See it worked","level":6,"route":"#/stop/area-triangles"},"idea-area-triangles-case2":{"id":"idea-area-triangles-case2","kind":"idea","src":"stop:area-triangles#case2","title":"Triangles and parallelograms: A right-angled triangle","body":"The upright side IS the height. The triangle is half of a rectangle, so halve base × height.","cta":"See it worked","level":6,"route":"#/stop/area-triangles"},"worked-area-triangles-worked2":{"id":"worked-area-triangles-worked2","kind":"worked","src":"stop:area-triangles#worked2","title":"Worked out — Triangles and parallelograms: A right-angled triangle","body":"A right-angled triangle has a base of 6 cm and a height of 4 cm. What is its area, in cm²?: The parallelogram (or rectangle) it is half of: 6 × 4 → 24 · The triangle is half of that → 12","cta":"Watch it step by step","level":6,"route":"#/stop/area-triangles"},"idea-area-triangles-case3":{"id":"idea-area-triangles-case3","kind":"idea","src":"stop:area-triangles#case3","title":"Triangles and parallelograms: Any triangle","body":"The height is the dashed line from the top straight down to the base. Two copies make a parallelogram, so halve base × height.","cta":"See it worked","level":6,"route":"#/stop/area-triangles"},"worked-area-triangles-worked3":{"id":"worked-area-triangles-worked3","kind":"worked","src":"stop:area-triangles#worked3","title":"Worked out — Triangles and parallelograms: Any triangle","body":"A triangle has a base of 10 cm and a height of 6 cm. What is its area, in cm²?: The parallelogram (or rectangle) it is half of: 10 × 6 → 60 · The triangle is half of that → 30","cta":"Watch it step by step","level":6,"route":"#/stop/area-triangles"},"why-area-triangles-why1":{"id":"why-area-triangles-why1","kind":"why","src":"stop:area-triangles#why1","title":"Why “Triangles and parallelograms” works","body":"Now draw a triangle and a copy of it turned upside down. Put the two together along a sloping side and they make a parallelogram with the same base and height. The triangle is exactly half of it: ½ × base × height.","cta":"See why","level":6,"route":"#/stop/area-triangles"},"why-area-triangles-why2":{"id":"why-area-triangles-why2","kind":"why","src":"stop:area-triangles#why2","title":"Why “Triangles and parallelograms” works","body":"That is why the sloping side never matters. A leaning shape and an upright one with the same base and straight-up height cover the same area — like a stack of coins pushed sideways.","cta":"See why","level":6,"route":"#/stop/area-triangles"},"algebra-area-triangles-alg":{"id":"algebra-area-triangles-alg","kind":"algebra","src":"stop:area-triangles#alg","title":"The algebra behind “Triangles and parallelograms”","body":"parallelogram: A = b × h · triangle: A = ½ × b × h","cta":"See why","level":6,"route":"#/stop/area-triangles"},"moment-area-triangles-beat4":{"id":"moment-area-triangles-beat4","kind":"moment","src":"story:area-triangles#beat4","badge":{"id":"story","label":"A story"},"title":"The market awning — on the notepad","body":"Vesper: A triangle flag with the same base and height is half. 9 × 4 ÷ 2 = 18","cta":"Read the story","level":6,"route":"#/stop/area-triangles"},"moral-area-triangles-beat5":{"id":"moral-area-triangles-beat5","kind":"moral","src":"story:area-triangles#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The market awning”","body":"So the awning is 36 square metres. Straight-up height, never the slope.","cta":"Read the story","level":6,"route":"#/stop/area-triangles"},"try-area-triangles-L6":{"id":"try-area-triangles-L6","kind":"try","level":6,"src":"try:area-triangles@6/1#0","title":"Triangles and parallelograms — your turn","route":"#/stop/area-triangles","cta":"Practise this stop","play":{"q":"A parallelogram has a base of 10 cm and a height of 4 cm. What is its area, in cm²?","opts":["40","10","4"],"after":"A parallelogram is base × height. A triangle is half of that: ½ × base × height. Always the straight-up height, never the slope."}},"hook-mixed-numbers-hook":{"id":"hook-mixed-numbers-hook","kind":"hook","src":"stop:mixed-numbers#hook","title":"Can you? — Mixed numbers and top-heavy fractions","body":"2 3/4 pies — how many quarters is that?","cta":"Find out how","level":6,"route":"#/stop/mixed-numbers"},"worked-mixed-numbers-worked0":{"id":"worked-mixed-numbers-worked0","kind":"worked","src":"stop:mixed-numbers#worked0","title":"Worked out — Mixed numbers and top-heavy fractions: Mixed to top-heavy","body":"Write 2 3/4 as an improper fraction: Pieces in the wholes: 2 × 4 → 8 · Add the 3 extra → 11 · Over 4 → 11/4","cta":"Watch it step by step","level":6,"route":"#/stop/mixed-numbers"},"worked-mixed-numbers-worked1":{"id":"worked-mixed-numbers-worked1","kind":"worked","src":"stop:mixed-numbers#worked1","title":"Worked out — Mixed numbers and top-heavy fractions: How many wholes?","body":"11/4 as a mixed number: how many whole ones?: How many pieces make one whole? → 4 · How many whole 4s fit in 11? → 2","cta":"Watch it step by step","level":6,"route":"#/stop/mixed-numbers"},"worked-mixed-numbers-worked2":{"id":"worked-mixed-numbers-worked2","kind":"worked","src":"stop:mixed-numbers#worked2","title":"Worked out — Mixed numbers and top-heavy fractions: Pieces left over","body":"13/5 = 2 and ?/5: 2 wholes use 2 × 5 pieces → 10 · Pieces left over from 13 → 3","cta":"Watch it step by step","level":6,"route":"#/stop/mixed-numbers"},"why-mixed-numbers-why2":{"id":"why-mixed-numbers-why2","kind":"why","src":"stop:mixed-numbers#why2","title":"Why “Mixed numbers and top-heavy fractions” works","body":"A \"top-heavy\" (improper) fraction is not wrong, just unfinished. Both names describe the same pile of pieces — one counts the pieces, the other counts whole pies first.","cta":"See why","level":6,"route":"#/stop/mixed-numbers"},"moment-mixed-numbers-beat3":{"id":"moment-mixed-numbers-beat3","kind":"moment","src":"story:mixed-numbers#beat3","badge":{"id":"story","label":"A story"},"title":"Pies in quarters — on the notepad","body":"Rafi: …and the 3 extra quarters. 8 + 3 = 11","cta":"Read the story","level":6,"route":"#/stop/mixed-numbers"},"try-mixed-numbers-L6":{"id":"try-mixed-numbers-L6","kind":"try","level":6,"src":"try:mixed-numbers@6/2#0","title":"Mixed numbers and top-heavy fractions — your turn","route":"#/stop/mixed-numbers","cta":"Practise this stop","play":{"q":"14/4 = 3 and ?/4 = ?","opts":["2","12","3"],"after":"Each whole is as many pieces as the bottom number. Multiply, then add the extra pieces."}},"trick-add-different-bottoms-idea":{"id":"trick-add-different-bottoms-idea","kind":"trick","src":"stop:add-different-bottoms#idea","title":"Adding different-sized slices","body":"Re-cut both into the same size of piece, then add the tops. You cannot add thirds and quarters straight away, any more than you can add 3 metres and 4 centimetres and call it 7. First make them the same kind of thing.","cta":"Learn the trick","level":6,"route":"#/stop/add-different-bottoms"},"story-add-different-bottoms-open":{"id":"story-add-different-bottoms-open","kind":"story","src":"story:add-different-bottoms#open","badge":{"id":"story","label":"A story"},"title":"Flour in two jugs","body":"Mira pours 1/3 of a jug of milk into the bowl, then 1/4 of a jug more. — with Mira and Rafi.","art":"art/s-bakery.webp","cta":"Read the story","level":6,"route":"#/stop/add-different-bottoms"},"hook-add-different-bottoms-hook":{"id":"hook-add-different-bottoms-hook","kind":"hook","src":"stop:add-different-bottoms#hook","title":"Can you? — Adding different-sized slices","body":"1/3 + 1/4 — the slices are different sizes. Now what?","cta":"Find out how","level":6,"route":"#/stop/add-different-bottoms"},"idea-add-different-bottoms-case0":{"id":"idea-add-different-bottoms-case0","kind":"idea","src":"stop:add-different-bottoms#case0","title":"Adding different-sized slices: Adding: one bottom fits","body":"3 goes into 6, so sixths already fit both. Only the thirds need cutting smaller.","cta":"See it worked","level":6,"route":"#/stop/add-different-bottoms"},"worked-add-different-bottoms-worked0":{"id":"worked-add-different-bottoms-worked0","kind":"worked","src":"stop:add-different-bottoms#worked0","title":"Worked out — Adding different-sized slices: Adding: one bottom fits","body":"1/3 + 1/6: A bottom that both 3 and 6 go into → 6 · 1/3 = ?/6 → 2 · 1/6 = ?/6 → 1 · Add the tops, keep the bottom → 3/6","cta":"Watch it step by step","level":6,"route":"#/stop/add-different-bottoms"},"idea-add-different-bottoms-case1":{"id":"idea-add-different-bottoms-case1","kind":"idea","src":"stop:add-different-bottoms#case1","title":"Adding different-sized slices: Adding: re-cut both","body":"Neither bottom goes into the other, so find a new bottom both go into and re-cut both fractions.","cta":"See it worked","level":6,"route":"#/stop/add-different-bottoms"},"worked-add-different-bottoms-worked1":{"id":"worked-add-different-bottoms-worked1","kind":"worked","src":"stop:add-different-bottoms#worked1","title":"Worked out — Adding different-sized slices: Adding: re-cut both","body":"1/3 + 1/4: A bottom that both 3 and 4 go into → 12 · 1/3 = ?/12 → 4 · 1/4 = ?/12 → 3 · Add the tops, keep the bottom → 7/12","cta":"Watch it step by step","level":6,"route":"#/stop/add-different-bottoms"},"idea-add-different-bottoms-case2":{"id":"idea-add-different-bottoms-case2","kind":"idea","src":"stop:add-different-bottoms#case2","title":"Adding different-sized slices: Taking away: one fits","body":"Same first step as adding — make the pieces match — then take the tops away.","cta":"See it worked","level":6,"route":"#/stop/add-different-bottoms"},"worked-add-different-bottoms-worked2":{"id":"worked-add-different-bottoms-worked2","kind":"worked","src":"stop:add-different-bottoms#worked2","title":"Worked out — Adding different-sized slices: Taking away: one fits","body":"3/4 − 1/2: A bottom that both 4 and 2 go into → 4 · 3/4 = ?/4 → 3 · 1/2 = ?/4 → 2 · Take the tops, keep the bottom → 1/4","cta":"Watch it step by step","level":6,"route":"#/stop/add-different-bottoms"},"idea-add-different-bottoms-case3":{"id":"idea-add-different-bottoms-case3","kind":"idea","src":"stop:add-different-bottoms#case3","title":"Adding different-sized slices: Taking away: re-cut both","body":"Re-cut both into a shared size first; only then can one be taken from the other.","cta":"See it worked","level":6,"route":"#/stop/add-different-bottoms"},"why-add-different-bottoms-why1":{"id":"why-add-different-bottoms-why1","kind":"why","src":"stop:add-different-bottoms#why1","title":"Why “Adding different-sized slices” works","body":"Twelfths fit both: every third is 4 twelfths and every quarter is 3 twelfths (12 is a number both 3 and 4 go into). So 1/3 + 1/4 = 4/12 + 3/12 = 7/12.","cta":"See why","level":6,"route":"#/stop/add-different-bottoms"},"why-add-different-bottoms-why2":{"id":"why-add-different-bottoms-why2","kind":"why","src":"stop:add-different-bottoms#why2","title":"Why “Adding different-sized slices” works","body":"Changing to twelfths is only equivalent fractions — the same share, cut smaller — so nothing about the amounts has changed. Once the pieces match, it is the easy sum from the last stop, and taking away works the same way. Sometimes one bottom already goes into the other — thirds and sixths — and then only the thirds need re-cutting: 1/3 = 2/6.","cta":"See why","level":6,"route":"#/stop/add-different-bottoms"},"algebra-add-different-bottoms-alg":{"id":"algebra-add-different-bottoms-alg","kind":"algebra","src":"stop:add-different-bottoms#alg","title":"The algebra behind “Adding different-sized slices”","body":"a/b ± c/d = (a × L/b ± c × L/d)/L, L a common multiple of b and d","cta":"See why","level":6,"route":"#/stop/add-different-bottoms"},"moment-add-different-bottoms-beat3":{"id":"moment-add-different-bottoms-beat3","kind":"moment","src":"story:add-different-bottoms#beat3","badge":{"id":"story","label":"A story"},"title":"Flour in two jugs — on the notepad","body":"Mira: One third is four twelfths. 12 ÷ 3 = 4","cta":"Read the story","level":6,"route":"#/stop/add-different-bottoms"},"moral-add-different-bottoms-beat5":{"id":"moral-add-different-bottoms-beat5","kind":"moral","src":"story:add-different-bottoms#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “Flour in two jugs”","body":"Four twelfths and three twelfths make seven twelfths of a jug.","cta":"Read the story","level":6,"route":"#/stop/add-different-bottoms"},"try-add-different-bottoms-L6":{"id":"try-add-different-bottoms-L6","kind":"try","level":6,"src":"try:add-different-bottoms@6/1#0","title":"Adding different-sized slices — your turn","route":"#/stop/add-different-bottoms","cta":"Practise this stop","play":{"q":"3/4 + 8/12 = ?","opts":["17/12","12","9"],"after":"Re-cut both into the same size of piece, then add the tops."}},"trick-multiply-fractions-idea":{"id":"trick-multiply-fractions-idea","kind":"trick","src":"stop:multiply-fractions#idea","title":"Multiplying fractions","body":"Multiply the tops, multiply the bottoms. A whole number times a fraction is just repeated adding: 3 × 2/5 is 2/5 + 2/5 + 2/5 = 6/5. The pieces stay fifths; you just have three times as many.","cta":"Learn the trick","level":6,"route":"#/stop/multiply-fractions"},"story-multiply-fractions-open":{"id":"story-multiply-fractions-open","kind":"story","src":"story:multiply-fractions#open","badge":{"id":"story","label":"A story"},"title":"Half of the rest","body":"Three quarters of a tray of flapjack is left. Kwame says Nova can have two thirds of what is left. — with Kwame and Nova.","art":"art/s-kitchen.webp","cta":"Read the story","level":6,"route":"#/stop/multiply-fractions"},"hook-multiply-fractions-hook":{"id":"hook-multiply-fractions-hook","kind":"hook","src":"stop:multiply-fractions#hook","title":"Can you? — Multiplying fractions","body":"2/3 × 3/4 — why do you just multiply straight across?","cta":"Find out how","level":6,"route":"#/stop/multiply-fractions"},"idea-multiply-fractions-case0":{"id":"idea-multiply-fractions-case0","kind":"idea","src":"stop:multiply-fractions#case0","title":"Multiplying fractions: Whole number × fraction","body":"This is repeated adding of the same slice, so the slices stay the same size: multiply the top, keep the bottom.","cta":"See it worked","level":6,"route":"#/stop/multiply-fractions"},"worked-multiply-fractions-worked0":{"id":"worked-multiply-fractions-worked0","kind":"worked","src":"stop:multiply-fractions#worked0","title":"Worked out — Multiplying fractions: Whole number × fraction","body":"3 × 2/5: Tops: 3 × 2 → 6 · The pieces are the same size — keep the bottom → 6/5","cta":"Watch it step by step","level":6,"route":"#/stop/multiply-fractions"},"idea-multiply-fractions-case1":{"id":"idea-multiply-fractions-case1","kind":"idea","src":"stop:multiply-fractions#case1","title":"Multiplying fractions: Fraction × fraction","body":"× means \"of\" here: part of a part. Multiply the tops to count your squares, and the bottoms to count them all.","cta":"See it worked","level":6,"route":"#/stop/multiply-fractions"},"worked-multiply-fractions-worked1":{"id":"worked-multiply-fractions-worked1","kind":"worked","src":"stop:multiply-fractions#worked1","title":"Worked out — Multiplying fractions: Fraction × fraction","body":"2/3 × 3/4: Tops: 2 × 3 → 6 · Bottoms: 3 × 4 → 12 · Top over bottom → 6/12","cta":"Watch it step by step","level":6,"route":"#/stop/multiply-fractions"},"why-multiply-fractions-why1":{"id":"why-multiply-fractions-why1","kind":"why","src":"stop:multiply-fractions#why1","title":"Why “Multiplying fractions” works","body":"\"×\" between two fractions means \"of\". 2/3 × 3/4 is two-thirds OF three-quarters. Picture a tray cut into 3 rows and 4 columns: 12 little squares, so each is 1/12 of the tray.","cta":"See why","level":6,"route":"#/stop/multiply-fractions"},"why-multiply-fractions-why2":{"id":"why-multiply-fractions-why2","kind":"why","src":"stop:multiply-fractions#why2","title":"Why “Multiplying fractions” works","body":"Three-quarters of the tray is 3 columns. Two-thirds of that is 2 rows of those 3 columns: 2 × 3 = 6 squares out of 3 × 4 = 12. The tops multiply to count your squares; the bottoms multiply to count all the squares.","cta":"See why","level":6,"route":"#/stop/multiply-fractions"},"moment-multiply-fractions-beat3":{"id":"moment-multiply-fractions-beat3","kind":"moment","src":"story:multiply-fractions#beat3","badge":{"id":"story","label":"A story"},"title":"Half of the rest — on the notepad","body":"Kwame: Three columns are left, and you take 2 rows of them. 2 × 3 = 6","cta":"Read the story","level":6,"route":"#/stop/multiply-fractions"},"moral-multiply-fractions-beat5":{"id":"moral-multiply-fractions-beat5","kind":"moral","src":"story:multiply-fractions#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Half of the rest”","body":"Tops times tops, bottoms times bottoms.","cta":"Read the story","level":6,"route":"#/stop/multiply-fractions"},"try-multiply-fractions-L6":{"id":"try-multiply-fractions-L6","kind":"try","level":6,"src":"try:multiply-fractions@6/1#0","title":"Multiplying fractions — your turn","route":"#/stop/multiply-fractions","cta":"Practise this stop","play":{"q":"5 × 1/5 = ?","opts":["5/5","5","6/5"],"after":"Multiply the tops, multiply the bottoms."}},"trick-divide-fractions-idea":{"id":"trick-divide-fractions-idea","kind":"trick","src":"stop:divide-fractions#idea","title":"Dividing by a fraction","body":"Keep the first, change ÷ to ×, flip the second. Dividing asks \"how many of these fit in that?\" How many halves fit in 3 pies? Each pie holds 2 halves, so 3 pies hold 6. Dividing by 1/2 is the same as multiplying by 2 — the answer is BIGGER, because halves are small.","cta":"Learn the trick","level":6,"route":"#/stop/divide-fractions"},"story-divide-fractions-open":{"id":"story-divide-fractions-open","kind":"story","src":"story:divide-fractions#open","badge":{"id":"story","label":"A story"},"title":"How many helpings?","body":"The bakery has 6 cakes. One helping is two thirds of a cake. How many helpings is that? — with Vesper and Dax.","art":"art/s-bakery.webp","cta":"Read the story","level":6,"route":"#/stop/divide-fractions"},"idea-divide-fractions-case0":{"id":"idea-divide-fractions-case0","kind":"idea","src":"stop:divide-fractions#case0","title":"Dividing by a fraction: Whole ÷ a unit fraction","body":"How many halves fit in 3? Each whole holds 2, so multiply the wholes by the bottom number.","cta":"See it worked","level":6,"route":"#/stop/divide-fractions"},"idea-divide-fractions-case1":{"id":"idea-divide-fractions-case1","kind":"idea","src":"stop:divide-fractions#case1","title":"Dividing by a fraction: Whole ÷ a bigger fraction","body":"Count the pieces first, then group them into helpings the size of the top number: multiply, then divide.","cta":"See it worked","level":6,"route":"#/stop/divide-fractions"},"idea-divide-fractions-case2":{"id":"idea-divide-fractions-case2","kind":"idea","src":"stop:divide-fractions#case2","title":"Dividing by a fraction: Fraction ÷ fraction","body":"Now both are fractions. Keep the first, change ÷ to ×, flip the second, and multiply straight across.","cta":"See it worked","level":6,"route":"#/stop/divide-fractions"},"why-divide-fractions-why1":{"id":"why-divide-fractions-why1","kind":"why","src":"stop:divide-fractions#why1","title":"Why “Dividing by a fraction” works","body":"Now 6 ÷ 2/3. First count thirds: 6 pies hold 6 × 3 = 18 thirds. But each helping is TWO thirds, so group them in twos: 18 ÷ 2 = 9 helpings. You multiplied by 3 and divided by 2 — which is multiplying by 3/2, the fraction flipped.","cta":"See why","level":6,"route":"#/stop/divide-fractions"},"algebra-divide-fractions-alg":{"id":"algebra-divide-fractions-alg","kind":"algebra","src":"stop:divide-fractions#alg","title":"The algebra behind “Dividing by a fraction”","body":"a/b ÷ c/d = a/b × d/c","cta":"See why","level":6,"route":"#/stop/divide-fractions"},"moral-divide-fractions-beat5":{"id":"moral-divide-fractions-beat5","kind":"moral","src":"story:divide-fractions#beat5","badge":{"id":"story","label":"A story"},"title":"Vesper, in “How many helpings?”","body":"Times by 3, divide by 2. Flip it and multiply.","cta":"Read the story","level":6,"route":"#/stop/divide-fractions"},"try-divide-fractions-L6":{"id":"try-divide-fractions-L6","kind":"try","level":6,"src":"try:divide-fractions@6/1#0","title":"Dividing by a fraction — your turn","route":"#/stop/divide-fractions","cta":"Practise this stop","play":{"q":"4 ÷ 1/2 = ?","opts":["8","2","9"],"after":"Keep the first, change ÷ to ×, flip the second."}},"hook-angles-on-a-line-hook":{"id":"hook-angles-on-a-line-hook","kind":"hook","src":"stop:angles-on-a-line#hook","title":"Can you? — Angles on a line and round a point","body":"Two angles sit side by side on a straight line. One is 125°. The other?","cta":"Find out how","level":6,"route":"#/stop/angles-on-a-line"},"worked-angles-on-a-line-worked0":{"id":"worked-angles-on-a-line-worked0","kind":"worked","src":"stop:angles-on-a-line#worked0","title":"Worked out — Angles on a line and round a point: On a straight line","body":"Angles on a straight line: 125° and ?. Find the missing angle.: Angles on a straight line make → 180 · The angle you know → 125 · 180 − 125 → 55","cta":"Watch it step by step","level":6,"route":"#/stop/angles-on-a-line"},"worked-angles-on-a-line-worked1":{"id":"worked-angles-on-a-line-worked1","kind":"worked","src":"stop:angles-on-a-line#worked1","title":"Worked out — Angles on a line and round a point: Round a point","body":"Angles around a point: 100°, 120°, 60° and ?. Find the missing angle.: All the way round a point makes → 360 · Add the angles you know → 280 · 360 − 280 → 80","cta":"Watch it step by step","level":6,"route":"#/stop/angles-on-a-line"},"why-angles-on-a-line-why2":{"id":"why-angles-on-a-line-why2","kind":"why","src":"stop:angles-on-a-line#why2","title":"Why “Angles on a line and round a point” works","body":"So a missing angle is never a mystery: add the ones you know and see how much of the 180° or 360° is left over.","cta":"See why","level":6,"route":"#/stop/angles-on-a-line"},"moment-angles-on-a-line-beat4":{"id":"moment-angles-on-a-line-beat4","kind":"moment","src":"story:angles-on-a-line#beat4","badge":{"id":"story","label":"A story"},"title":"The see-saw — on the notepad","body":"Theo: Take away the one you know. 180 − 125 = 55","cta":"Read the story","level":6,"route":"#/stop/angles-on-a-line"},"try-angles-on-a-line-L6":{"id":"try-angles-on-a-line-L6","kind":"try","level":6,"src":"try:angles-on-a-line@6/2#0","title":"Angles on a line and round a point — your turn","route":"#/stop/angles-on-a-line","cta":"Practise this stop","play":{"q":"Angles on a straight line: 80°, 75° and ?. Find the missing angle.","opts":["25","180","155"],"after":"Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know."}},"trick-angles-in-a-shape-idea":{"id":"trick-angles-in-a-shape-idea","kind":"trick","src":"stop:angles-in-a-shape#idea","title":"Angles inside a shape","body":"The angles of any triangle add up to 180°; of any four-sided shape, 360°. Take away the ones you know. Draw any triangle on paper and tear off its three corners. Put the three torn points together, side by side: they always make a straight line. A straight line is 180°, so the three angles of every triangle — tall, flat, big or tiny — add up to 180°.","cta":"Learn the trick","level":6,"route":"#/stop/angles-in-a-shape"},"story-angles-in-a-shape-open":{"id":"story-angles-in-a-shape-open","kind":"story","src":"story:angles-in-a-shape#open","badge":{"id":"story","label":"A story"},"title":"Torn corners","body":"Kwame cuts out a paper triangle. Two of its angles are 50° and 60°. — with Kwame and Mira.","art":"art/s-room.webp","cta":"Read the story","level":6,"route":"#/stop/angles-in-a-shape"},"hook-angles-in-a-shape-hook":{"id":"hook-angles-in-a-shape-hook","kind":"hook","src":"stop:angles-in-a-shape#hook","title":"Can you? — Angles inside a shape","body":"A triangle has angles of 50° and 60°. What is the third — without measuring?","cta":"Find out how","level":6,"route":"#/stop/angles-in-a-shape"},"idea-angles-in-a-shape-case0":{"id":"idea-angles-in-a-shape-case0","kind":"idea","src":"stop:angles-in-a-shape#case0","title":"Angles inside a shape: A triangle","body":"Three angles always fill 180° — tear the corners off and they make a straight line.","cta":"See it worked","level":6,"route":"#/stop/angles-in-a-shape"},"worked-angles-in-a-shape-worked0":{"id":"worked-angles-in-a-shape-worked0","kind":"worked","src":"stop:angles-in-a-shape#worked0","title":"Worked out — Angles inside a shape: A triangle","body":"A triangle has angles of 50° and 60°. What is the third angle?: Angles in a triangle add up to → 180 · Add the two you know → 110 · 180 − 110 → 70","cta":"Watch it step by step","level":6,"route":"#/stop/angles-in-a-shape"},"idea-angles-in-a-shape-case1":{"id":"idea-angles-in-a-shape-case1","kind":"idea","src":"stop:angles-in-a-shape#case1","title":"Angles inside a shape: An isosceles triangle","body":"You know only ONE angle, but the other two are equal. Take the top angle from 180°, then halve what is left.","cta":"See it worked","level":6,"route":"#/stop/angles-in-a-shape"},"worked-angles-in-a-shape-worked1":{"id":"worked-angles-in-a-shape-worked1","kind":"worked","src":"stop:angles-in-a-shape#worked1","title":"Worked out — Angles inside a shape: An isosceles triangle","body":"An isosceles triangle has a top angle of 40°. What is each of its two equal base angles?: Angles in a triangle add up to → 180 · 180 − 40 → 140 · Shared between the two equal angles → 70","cta":"Watch it step by step","level":6,"route":"#/stop/angles-in-a-shape"},"idea-angles-in-a-shape-case2":{"id":"idea-angles-in-a-shape-case2","kind":"idea","src":"stop:angles-in-a-shape#case2","title":"Angles inside a shape: A four-sided shape","body":"Cut it corner to corner into two triangles: two lots of 180° make 360°.","cta":"See it worked","level":6,"route":"#/stop/angles-in-a-shape"},"worked-angles-in-a-shape-worked2":{"id":"worked-angles-in-a-shape-worked2","kind":"worked","src":"stop:angles-in-a-shape#worked2","title":"Worked out — Angles inside a shape: A four-sided shape","body":"A four-sided shape has angles of 70°, 95° and 110°. What is the fourth angle?: Angles in a four-sided shape add up to → 360 · Add the three you know → 275 · 360 − 275 → 85","cta":"Watch it step by step","level":6,"route":"#/stop/angles-in-a-shape"},"why-angles-in-a-shape-why1":{"id":"why-angles-in-a-shape-why1","kind":"why","src":"stop:angles-in-a-shape#why1","title":"Why “Angles inside a shape” works","body":"A four-sided shape can be cut corner to corner into two triangles. Every angle of the shape is shared out between the two triangles and nothing else is added, so its angles are two triangles' worth: 2 × 180° = 360°.","cta":"See why","level":6,"route":"#/stop/angles-in-a-shape"},"why-angles-in-a-shape-why2":{"id":"why-angles-in-a-shape-why2","kind":"why","src":"stop:angles-in-a-shape#why2","title":"Why “Angles inside a shape” works","body":"In an isosceles triangle the two base angles are equal (it is its own mirror image), so once you know the top angle, what is left of the 180° is split into two equal halves.","cta":"See why","level":6,"route":"#/stop/angles-in-a-shape"},"algebra-angles-in-a-shape-alg":{"id":"algebra-angles-in-a-shape-alg","kind":"algebra","src":"stop:angles-in-a-shape#alg","title":"The algebra behind “Angles inside a shape”","body":"triangle: a + b + c = 180° · quadrilateral: a + b + c + d = 360°","cta":"See why","level":6,"route":"#/stop/angles-in-a-shape"},"moment-angles-in-a-shape-beat3":{"id":"moment-angles-in-a-shape-beat3","kind":"moment","src":"story:angles-in-a-shape#beat3","badge":{"id":"story","label":"A story"},"title":"Torn corners — on the notepad","body":"Mira: So the three angles fill 180°. Take away the two you know. 180 − 110 = 70","cta":"Read the story","level":6,"route":"#/stop/angles-in-a-shape"},"moral-angles-in-a-shape-beat6":{"id":"moral-angles-in-a-shape-beat6","kind":"moral","src":"story:angles-in-a-shape#beat6","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Torn corners”","body":"The third angle of my triangle is 70°.","cta":"Read the story","level":6,"route":"#/stop/angles-in-a-shape"},"try-angles-in-a-shape-L6":{"id":"try-angles-in-a-shape-L6","kind":"try","level":6,"src":"try:angles-in-a-shape@6/1#0","title":"Angles inside a shape — your turn","route":"#/stop/angles-in-a-shape","cta":"Practise this stop","play":{"q":"A triangle has angles of 70° and 69°. What is the third angle?","opts":["41","180","139"],"after":"The angles of any triangle add up to 180°; of any four-sided shape, 360°. Take away the ones you know."}},"trick-compare-integers-idea":{"id":"trick-compare-integers-idea","kind":"trick","src":"stop:compare-integers#idea","title":"Higher or lower?","body":"Picture the lift shaft: the number higher up the shaft is always the bigger one. On a number line every number is bigger than all the numbers below it. Stand the line up and it is the lift shaft of a mine: ground is 0, and the levels under it are −1, −2, −3, going down. Going up means getting bigger — even when you are still underground.","cta":"Learn the trick","level":6,"route":"#/stop/compare-integers"},"story-compare-integers-open":{"id":"story-compare-integers-open","kind":"story","src":"story:compare-integers#open","badge":{"id":"story","label":"A story"},"title":"The coldest night","body":"A winter night. Pip’s thermometer reads −7 °C. Nova’s, across the street, reads −3 °C. — with Pip and Nova.","art":"art/s-night.webp","cta":"Read the story","level":6,"route":"#/stop/compare-integers"},"hook-compare-integers-hook":{"id":"hook-compare-integers-hook","kind":"hook","src":"stop:compare-integers#hook","title":"Can you? — Higher or lower?","body":"Level −7 or level −3 — which one is deeper? And which number is bigger?","cta":"Find out how","level":6,"route":"#/stop/compare-integers"},"idea-compare-integers-case0":{"id":"idea-compare-integers-case0","kind":"idea","src":"stop:compare-integers#case0","title":"Higher or lower?: Both below ground","body":"Both numbers are negative, so the one nearer to zero is higher up the shaft — and higher up means bigger, even though its digit looks smaller.","cta":"See it worked","level":6,"route":"#/stop/compare-integers"},"worked-compare-integers-worked0":{"id":"worked-compare-integers-worked0","kind":"worked","src":"stop:compare-integers#worked0","title":"Worked out — Higher or lower?: Both below ground","body":"−7  ?  −3: Which is higher up the shaft: −7 or −3? → -3 · So the sign between them is → <","cta":"Watch it step by step","level":6,"route":"#/stop/compare-integers"},"idea-compare-integers-case1":{"id":"idea-compare-integers-case1","kind":"idea","src":"stop:compare-integers#case1","title":"Higher or lower?: One each side of ground","body":"A number above ground beats every number below it, however big the digits underground look.","cta":"See it worked","level":6,"route":"#/stop/compare-integers"},"worked-compare-integers-worked1":{"id":"worked-compare-integers-worked1","kind":"worked","src":"stop:compare-integers#worked1","title":"Worked out — Higher or lower?: One each side of ground","body":"4  ?  −6: Which is higher up the shaft: 4 or −6? → 4 · So the sign between them is → >","cta":"Watch it step by step","level":6,"route":"#/stop/compare-integers"},"idea-compare-integers-case2":{"id":"idea-compare-integers-case2","kind":"idea","src":"stop:compare-integers#case2","title":"Higher or lower?: Zero and a negative","body":"Zero is ground level itself. Every negative number is below it, so every negative number is less than 0.","cta":"See it worked","level":6,"route":"#/stop/compare-integers"},"worked-compare-integers-worked2":{"id":"worked-compare-integers-worked2","kind":"worked","src":"stop:compare-integers#worked2","title":"Worked out — Higher or lower?: Zero and a negative","body":"0  ?  −2: Which is higher up the shaft: 0 or −2? → 0 · So the sign between them is → >","cta":"Watch it step by step","level":6,"route":"#/stop/compare-integers"},"why-compare-integers-why1":{"id":"why-compare-integers-why1","kind":"why","src":"stop:compare-integers#why1","title":"Why “Higher or lower?” works","body":"So −3 is bigger than −7. That feels backwards, because 7 is bigger than 3. But −7 is seven levels down and −3 is only three: −3 is higher up the shaft. Being further below zero makes a number smaller, not bigger. It is the same on a thermometer: −7 °C is colder than −3 °C.","cta":"See why","level":6,"route":"#/stop/compare-integers"},"why-compare-integers-why2":{"id":"why-compare-integers-why2","kind":"why","src":"stop:compare-integers#why2","title":"Why “Higher or lower?” works","body":"Any number above ground beats any number below it, and 0 sits between them: −1 is less than 0, and 0 is less than 1. When both numbers are negative, the one with the smaller distance from zero is the bigger number.","cta":"See why","level":6,"route":"#/stop/compare-integers"},"algebra-compare-integers-alg":{"id":"algebra-compare-integers-alg","kind":"algebra","src":"stop:compare-integers#alg","title":"The algebra behind “Higher or lower?”","body":"a < b exactly when a is below b on the number line ; −7 < −3","cta":"See why","level":6,"route":"#/stop/compare-integers"},"moment-compare-integers-beat2":{"id":"moment-compare-integers-beat2","kind":"moment","src":"story:compare-integers#beat2","badge":{"id":"story","label":"A story"},"title":"The coldest night — on the notepad","body":"Nova: Which one is colder, though? Yours is seven below zero. Mine is only three below. 0 − 7 = -7","cta":"Read the story","level":6,"route":"#/stop/compare-integers"},"moral-compare-integers-beat5":{"id":"moral-compare-integers-beat5","kind":"moral","src":"story:compare-integers#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The coldest night”","body":"So −3 is the bigger number, and −7 is less than −3. The one higher up wins.","cta":"Read the story","level":6,"route":"#/stop/compare-integers"},"try-compare-integers-L6":{"id":"try-compare-integers-L6","kind":"try","level":6,"src":"try:compare-integers@6/1#0","title":"Higher or lower? — your turn","route":"#/stop/compare-integers","cta":"Practise this stop","play":{"q":"−5  ?  −3","opts":["<","=",">"],"after":"Picture the lift shaft: the number higher up the shaft is always the bigger one."}},"trick-lift-moves-idea":{"id":"trick-lift-moves-idea","kind":"trick","src":"stop:lift-moves#idea","title":"Riding the lift","body":"Ride to ground level first, then carry on with what is left of the trip. A lift trip that crosses ground level is really two trips. From −4 up to 0 is 4 levels. The trip was 9, so 4 of them are used just getting back to the surface, and 5 are left. Five above ground is level 5.","cta":"Learn the trick","level":6,"route":"#/stop/lift-moves"},"story-lift-moves-open":{"id":"story-lift-moves-open","kind":"story","src":"story:lift-moves#open","badge":{"id":"story","label":"A story"},"title":"The car park lift","body":"The car park under the city tower has four floors below ground. Dax and Suki get in the lift at level −4. — with Dax and Suki.","art":"art/s-city.webp","cta":"Read the story","level":6,"route":"#/stop/lift-moves"},"hook-lift-moves-hook":{"id":"hook-lift-moves-hook","kind":"hook","src":"stop:lift-moves#hook","title":"Can you? — Riding the lift","body":"The lift is on level −4. It goes up 9 levels. Is it on level 13 now?","cta":"Find out how","level":6,"route":"#/stop/lift-moves"},"idea-lift-moves-case0":{"id":"idea-lift-moves-case0","kind":"idea","src":"stop:lift-moves#case0","title":"Riding the lift: Down, still above ground","body":"The lift stays above ground, so this is an ordinary take-away — the numbers you already know.","cta":"See it worked","level":6,"route":"#/stop/lift-moves"},"worked-lift-moves-worked0":{"id":"worked-lift-moves-worked0","kind":"worked","src":"stop:lift-moves#worked0","title":"Worked out — Riding the lift: Down, still above ground","body":"The lift is on level 7. It goes down 3 levels. Which level is it on now?: 7 − 3 → 4","cta":"Watch it step by step","level":6,"route":"#/stop/lift-moves"},"idea-lift-moves-case1":{"id":"idea-lift-moves-case1","kind":"idea","src":"stop:lift-moves#case1","title":"Riding the lift: Landing on ground","body":"The trip is exactly as long as the distance to ground, so the lift stops on 0 — ground is a level too, neither above nor below.","cta":"See it worked","level":6,"route":"#/stop/lift-moves"},"worked-lift-moves-worked1":{"id":"worked-lift-moves-worked1","kind":"worked","src":"stop:lift-moves#worked1","title":"Worked out — Riding the lift: Landing on ground","body":"The lift is on level −5. It goes up 5 levels. Which level is it on now?: −5 + 5 → 0","cta":"Watch it step by step","level":6,"route":"#/stop/lift-moves"},"idea-lift-moves-case2":{"id":"idea-lift-moves-case2","kind":"idea","src":"stop:lift-moves#case2","title":"Riding the lift: Up past ground","body":"Ride up to 0 first, then carry on with what is left of the trip. Zero splits one hard sum into two easy ones.","cta":"See it worked","level":6,"route":"#/stop/lift-moves"},"worked-lift-moves-worked2":{"id":"worked-lift-moves-worked2","kind":"worked","src":"stop:lift-moves#worked2","title":"Worked out — Riding the lift: Up past ground","body":"The lift is on level −4. It goes up 9 levels. Which level is it on now?: From −4 up to 0 is → 4 · Still to go after 0: 9 − 4 → 5 · Past zero, so you land on → 5","cta":"Watch it step by step","level":6,"route":"#/stop/lift-moves"},"idea-lift-moves-case3":{"id":"idea-lift-moves-case3","kind":"idea","src":"stop:lift-moves#case3","title":"Riding the lift: Down past ground","body":"The same two trips the other way: down to 0, then the rest of the trip takes you underground.","cta":"See it worked","level":6,"route":"#/stop/lift-moves"},"worked-lift-moves-worked3":{"id":"worked-lift-moves-worked3","kind":"worked","src":"stop:lift-moves#worked3","title":"Worked out — Riding the lift: Down past ground","body":"The lift is on level 3. It goes down 8 levels. Which level is it on now?: From 3 down to 0 is → 3 · Still to go after 0: 8 − 3 → 5 · Past zero, so you land on → -5","cta":"Watch it step by step","level":6,"route":"#/stop/lift-moves"},"idea-lift-moves-case4":{"id":"idea-lift-moves-case4","kind":"idea","src":"stop:lift-moves#case4","title":"Riding the lift: Down, deeper underground","body":"Already below ground and going down: you get further from zero, so the distances add — and the number gets smaller.","cta":"See it worked","level":6,"route":"#/stop/lift-moves"},"worked-lift-moves-worked4":{"id":"worked-lift-moves-worked4","kind":"worked","src":"stop:lift-moves#worked4","title":"Worked out — Riding the lift: Down, deeper underground","body":"The lift is on level −6. It goes down 3 levels. Which level is it on now?: How far below 0 is −6? → 6 · Down 3 takes you further from 0: 6 + 3 → 9 · Still below zero, so you are at → -9","cta":"Watch it step by step","level":6,"route":"#/stop/lift-moves"},"idea-lift-moves-case5":{"id":"idea-lift-moves-case5","kind":"idea","src":"stop:lift-moves#case5","title":"Riding the lift: Up, still underground","body":"Going up underground brings you closer to zero, so the distance below ground shrinks — the number gets bigger.","cta":"See it worked","level":6,"route":"#/stop/lift-moves"},"worked-lift-moves-worked5":{"id":"worked-lift-moves-worked5","kind":"worked","src":"stop:lift-moves#worked5","title":"Worked out — Riding the lift: Up, still underground","body":"The lift is on level −6. It goes up 2 levels. Which level is it on now?: How far below 0 is −6? → 6 · Up 2 brings you closer to 0: 6 − 2 → 4 · Still below zero, so you are at → -4","cta":"Watch it step by step","level":6,"route":"#/stop/lift-moves"},"idea-lift-moves-case6":{"id":"idea-lift-moves-case6","kind":"idea","src":"stop:lift-moves#case6","title":"Riding the lift: Two trips in a row","body":"Do one trip at a time: find where the first one ends, then start the second from there.","cta":"See it worked","level":6,"route":"#/stop/lift-moves"},"worked-lift-moves-worked6":{"id":"worked-lift-moves-worked6","kind":"worked","src":"stop:lift-moves#worked6","title":"Worked out — Riding the lift: Two trips in a row","body":"The lift is on level −3. It goes up 8 levels, then down 12. Which level is it on now?: From −3, up 8. Where does the first trip end? → 5 · From 5, down 12 → -7","cta":"Watch it step by step","level":6,"route":"#/stop/lift-moves"},"why-lift-moves-why1":{"id":"why-lift-moves-why1","kind":"why","src":"stop:lift-moves#why1","title":"Why “Riding the lift” works","body":"Going down works the same way in the other direction. From level 3, going down 8: 3 levels bring you to ground, and the other 5 take you underground to −5. Zero is the stop in the middle that turns one hard sum into two easy ones.","cta":"See why","level":6,"route":"#/stop/lift-moves"},"why-lift-moves-why2":{"id":"why-lift-moves-why2","kind":"why","src":"stop:lift-moves#why2","title":"Why “Riding the lift” works","body":"If the trip never reaches ground, count distance from zero. From −6, going down 3 more puts you 9 below: −9. From −6, going up 2 brings you closer, only 4 below: −4. Going up always makes the number bigger, even underground.","cta":"See why","level":6,"route":"#/stop/lift-moves"},"algebra-lift-moves-alg":{"id":"algebra-lift-moves-alg","kind":"algebra","src":"stop:lift-moves#alg","title":"The algebra behind “Riding the lift”","body":"start + change = end ; −4 + 9 = 5 , 3 − 8 = −5","cta":"See why","level":6,"route":"#/stop/lift-moves"},"moment-lift-moves-beat4":{"id":"moment-lift-moves-beat4","kind":"moment","src":"story:lift-moves#beat4","badge":{"id":"story","label":"A story"},"title":"The car park lift — on the notepad","body":"Suki: That uses 4 of the 9. How many are left to go above ground? 9 − 4 = 5","cta":"Read the story","level":6,"route":"#/stop/lift-moves"},"moral-lift-moves-beat6":{"id":"moral-lift-moves-beat6","kind":"moral","src":"story:lift-moves#beat6","badge":{"id":"story","label":"A story"},"title":"Suki, in “The car park lift”","body":"Go to zero first, then carry on with what is left.","cta":"Read the story","level":6,"route":"#/stop/lift-moves"},"try-lift-moves-L6":{"id":"try-lift-moves-L6","kind":"try","level":6,"src":"try:lift-moves@6/1#0","title":"Riding the lift — your turn","route":"#/stop/lift-moves","cta":"Practise this stop","play":{"q":"The lift is on level 2. It goes down 2 levels. Which level is it on now?","opts":["0","1","10"],"after":"Ride to ground level first, then carry on with what is left of the trip."}},"trick-integer-gap-idea":{"id":"trick-integer-gap-idea","kind":"trick","src":"stop:integer-gap#idea","title":"How far apart?","body":"Measure each number’s distance from zero; add them if zero is between, take away if it is not. The distance of a number from zero is called its size, or absolute value, and is written with bars: |−6| = 6, because −6 is six levels below ground. Distance never has a minus sign — six levels is six levels whichever way you walk them.","cta":"Learn the trick","level":6,"route":"#/stop/integer-gap"},"story-integer-gap-open":{"id":"story-integer-gap-open","kind":"story","src":"story:integer-gap#open","badge":{"id":"story","label":"A story"},"title":"The diver and the gull","body":"At the harbour a diver is 6 metres under the water, at −6 m. A gull sits on a post 5 metres above it. — with Rafi and Nova.","art":"art/s-harbour.webp","cta":"Read the story","level":6,"route":"#/stop/integer-gap"},"hook-integer-gap-hook":{"id":"hook-integer-gap-hook","kind":"hook","src":"stop:integer-gap#hook","title":"Can you? — How far apart?","body":"One miner is on level −6, another is up on level 5. How many levels apart are they?","cta":"Find out how","level":6,"route":"#/stop/integer-gap"},"idea-integer-gap-case0":{"id":"idea-integer-gap-case0","kind":"idea","src":"stop:integer-gap#case0","title":"How far apart?: Zero is between them","body":"One is above ground and one below, so the gap is two trips glued together at 0 — add the two distances.","cta":"See it worked","level":6,"route":"#/stop/integer-gap"},"worked-integer-gap-worked0":{"id":"worked-integer-gap-worked0","kind":"worked","src":"stop:integer-gap#worked0","title":"Worked out — How far apart?: Zero is between them","body":"One miner is on level −6, another on level 5. How many levels apart are they?: From −6 up to 0 → 6 · From 0 up to 5 → 5 · Zero is between them, so add → 11","cta":"Watch it step by step","level":6,"route":"#/stop/integer-gap"},"idea-integer-gap-case1":{"id":"idea-integer-gap-case1","kind":"idea","src":"stop:integer-gap#case1","title":"How far apart?: Both below ground","body":"Zero is not between them, so do not add. The deeper one is further down by the difference of their distances — take away.","cta":"See it worked","level":6,"route":"#/stop/integer-gap"},"worked-integer-gap-worked1":{"id":"worked-integer-gap-worked1","kind":"worked","src":"stop:integer-gap#worked1","title":"Worked out — How far apart?: Both below ground","body":"One miner is on level −9, another on level −4. How many levels apart are they?: How far below 0 is −9? → 9 · How far below 0 is −4? → 4 · Both below zero, so take away: 9 − 4 → 5","cta":"Watch it step by step","level":6,"route":"#/stop/integer-gap"},"why-integer-gap-why1":{"id":"why-integer-gap-why1","kind":"why","src":"stop:integer-gap#why1","title":"Why “How far apart?” works","body":"When zero sits between two numbers, the gap between them is two trips glued together: from −6 up to ground is 6, from ground up to 5 is 5, so they are 11 apart. Add the two distances.","cta":"See why","level":6,"route":"#/stop/integer-gap"},"why-integer-gap-why2":{"id":"why-integer-gap-why2","kind":"why","src":"stop:integer-gap#why2","title":"Why “How far apart?” works","body":"When both are underground, zero is not between them. −9 is 9 below ground and −4 is 4 below; the deeper miner is 9 − 4 = 5 levels further down. Take the distances away. Either way it is the higher number minus the lower one: 5 − (−6) = 11 and −4 − (−9) = 5.","cta":"See why","level":6,"route":"#/stop/integer-gap"},"algebra-integer-gap-alg":{"id":"algebra-integer-gap-alg","kind":"algebra","src":"stop:integer-gap#alg","title":"The algebra behind “How far apart?”","body":"gap between a and b = |a − b| ; |−6| = 6","cta":"See why","level":6,"route":"#/stop/integer-gap"},"moment-integer-gap-beat4":{"id":"moment-integer-gap-beat4","kind":"moment","src":"story:integer-gap#beat4","badge":{"id":"story","label":"A story"},"title":"The diver and the gull — on the notepad","body":"Nova: And from the surface up to the gull is 5 more. 5 − 0 = 5","cta":"Read the story","level":6,"route":"#/stop/integer-gap"},"moral-integer-gap-beat6":{"id":"moral-integer-gap-beat6","kind":"moral","src":"story:integer-gap#beat6","badge":{"id":"story","label":"A story"},"title":"Nova, in “The diver and the gull”","body":"Eleven metres apart. The higher one minus the lower one.","cta":"Read the story","level":6,"route":"#/stop/integer-gap"},"try-integer-gap-L6":{"id":"try-integer-gap-L6","kind":"try","level":6,"src":"try:integer-gap@6/1#0","title":"How far apart? — your turn","route":"#/stop/integer-gap","cta":"Practise this stop","play":{"q":"One miner is on level −8, another on level 3. How many levels apart are they?","opts":["11","8","3"],"after":"Measure each number’s distance from zero; add them if zero is between, take away if it is not."}},"trick-add-negative-idea":{"id":"trick-add-negative-idea","kind":"trick","src":"stop:add-negative#idea","title":"Adding a negative","body":"Adding a negative number is the same as taking away its size: 5 + (−8) = 5 − 8. Think of a bank balance. Money in is a positive number, and a bill you owe is a negative one. If you have 5 coins and a bill for 8 arrives, adding the bill to your account takes 8 away: 5 + (−8) = 5 − 8. The account goes 3 below zero, −3. That is not a disaster; it is just a number that says “3 still owed”.","cta":"Learn the trick","level":6,"route":"#/stop/add-negative"},"story-add-negative-open":{"id":"story-add-negative-open","kind":"story","src":"story:add-negative#open","badge":{"id":"story","label":"A story"},"title":"The club account","body":"Pip runs the model-club account at the corner shop. It has 5 coins in it. A bill for 8 coins arrives. — with Ines and Pip.","art":"art/s-shop.webp","cta":"Read the story","level":6,"route":"#/stop/add-negative"},"hook-add-negative-hook":{"id":"hook-add-negative-hook","kind":"hook","src":"stop:add-negative#hook","title":"Can you? — Adding a negative","body":"5 + (−8). Adding makes things bigger… doesn’t it?","cta":"Find out how","level":6,"route":"#/stop/add-negative"},"idea-add-negative-case0":{"id":"idea-add-negative-case0","kind":"idea","src":"stop:add-negative#case0","title":"Adding a negative: Staying above ground","body":"Adding a negative means going down. Here the start is high enough that you never pass ground — an ordinary take-away.","cta":"See it worked","level":6,"route":"#/stop/add-negative"},"worked-add-negative-worked0":{"id":"worked-add-negative-worked0","kind":"worked","src":"stop:add-negative#worked0","title":"Worked out — Adding a negative: Staying above ground","body":"9 + (−4): Adding −4 is the same as going down by → 4 · 9 − 4 → 5","cta":"Watch it step by step","level":6,"route":"#/stop/add-negative"},"idea-add-negative-case1":{"id":"idea-add-negative-case1","kind":"idea","src":"stop:add-negative#case1","title":"Adding a negative: Down past ground","body":"Going down further than you are above ground: use up the levels to reach 0, then the rest take you below it.","cta":"See it worked","level":6,"route":"#/stop/add-negative"},"worked-add-negative-worked1":{"id":"worked-add-negative-worked1","kind":"worked","src":"stop:add-negative#worked1","title":"Worked out — Adding a negative: Down past ground","body":"5 + (−8): Adding −8 is the same as going down by → 8 · From 5 down to 0 is → 5 · Still to go after 0: 8 − 5 → 3 · Past zero, so you land on → -3","cta":"Watch it step by step","level":6,"route":"#/stop/add-negative"},"idea-add-negative-case2":{"id":"idea-add-negative-case2","kind":"idea","src":"stop:add-negative#case2","title":"Adding a negative: Starting below ground","body":"Already underground and going down again: like two bills, the distances add up to a bigger bill.","cta":"See it worked","level":6,"route":"#/stop/add-negative"},"worked-add-negative-worked2":{"id":"worked-add-negative-worked2","kind":"worked","src":"stop:add-negative#worked2","title":"Worked out — Adding a negative: Starting below ground","body":"−2 + (−6): Adding −6 is the same as going down by → 6 · How far below 0 is −2? → 2 · Down 6 takes you further from 0: 2 + 6 → 8 · Still below zero, so you are at → -8","cta":"Watch it step by step","level":6,"route":"#/stop/add-negative"},"why-add-negative-why1":{"id":"why-add-negative-why1","kind":"why","src":"stop:add-negative#why1","title":"Why “Adding a negative” works","body":"On the lift, adding a positive number means going up and adding a negative means going down. So 5 + (−8) is: start on level 5, go down 8. Five of the levels bring you to ground, three more take you to −3.","cta":"See why","level":6,"route":"#/stop/add-negative"},"why-add-negative-why2":{"id":"why-add-negative-why2","kind":"why","src":"stop:add-negative#why2","title":"Why “Adding a negative” works","body":"It works when you start underground too: −2 + (−6) is two below, then six more below — eight below, −8. Adding two negatives is like two bills: they add up to a bigger bill.","cta":"See why","level":6,"route":"#/stop/add-negative"},"moment-add-negative-beat4":{"id":"moment-add-negative-beat4","kind":"moment","src":"story:add-negative#beat4","badge":{"id":"story","label":"A story"},"title":"The club account — on the notepad","body":"Pip: And there are still 3 coins of the bill left to pay. 8 − 5 = 3","cta":"Read the story","level":6,"route":"#/stop/add-negative"},"moral-add-negative-beat5":{"id":"moral-add-negative-beat5","kind":"moral","src":"story:add-negative#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The club account”","body":"So the balance is −3. It just means 3 still owed. Nobody’s in trouble.","cta":"Read the story","level":6,"route":"#/stop/add-negative"},"try-add-negative-L6":{"id":"try-add-negative-L6","kind":"try","level":6,"src":"try:add-negative@6/1#0","title":"Adding a negative — your turn","route":"#/stop/add-negative","cta":"Practise this stop","play":{"q":"7 + (−10) = ?","opts":["-3","10","7"],"after":"Adding a negative number is the same as taking away its size: 5 + (−8) = 5 − 8."}},"trick-subtract-negative-idea":{"id":"trick-subtract-negative-idea","kind":"trick","src":"stop:subtract-negative#idea","title":"Taking away a negative","body":"Taking away a negative is the same as adding its size: 5 − (−3) = 5 + 3. Watch a pattern. 5 − 2 = 3. 5 − 1 = 4. 5 − 0 = 5. Each time you take away one less, the answer goes up by one. Carry the pattern on below zero: 5 − (−1) must be 6, 5 − (−2) must be 7, and 5 − (−3) must be 8. The pattern has no reason to stop at zero, and it does not.","cta":"Learn the trick","level":6,"route":"#/stop/subtract-negative"},"story-subtract-negative-open":{"id":"story-subtract-negative-open","kind":"story","src":"story:subtract-negative#open","badge":{"id":"story","label":"A story"},"title":"The pattern on the board","body":"Before the hall assembly, Kwame writes a column of sums on the whiteboard. Dax is sure the last one is wrong. — with Kwame and Dax.","art":"art/s-hall.webp","cta":"Read the story","level":6,"route":"#/stop/subtract-negative"},"hook-subtract-negative-hook":{"id":"hook-subtract-negative-hook","kind":"hook","src":"stop:subtract-negative#hook","title":"Can you? — Taking away a negative","body":"5 − (−3). How can taking something away make a number bigger?","cta":"Find out how","level":6,"route":"#/stop/subtract-negative"},"idea-subtract-negative-case0":{"id":"idea-subtract-negative-case0","kind":"idea","src":"stop:subtract-negative#case0","title":"Taking away a negative: Starting above ground","body":"The two minuses together mean add, so the lift goes up — and from above ground it simply climbs higher.","cta":"See it worked","level":6,"route":"#/stop/subtract-negative"},"worked-subtract-negative-worked0":{"id":"worked-subtract-negative-worked0","kind":"worked","src":"stop:subtract-negative#worked0","title":"Worked out — Taking away a negative: Starting above ground","body":"5 − (−3): Taking away −3 is the same as adding → 3 · 5 + 3 → 8","cta":"Watch it step by step","level":6,"route":"#/stop/subtract-negative"},"idea-subtract-negative-case1":{"id":"idea-subtract-negative-case1","kind":"idea","src":"stop:subtract-negative#case1","title":"Taking away a negative: Below ground, up past 0","body":"Turn it into an add first, then ride up: reach ground, and the rest of the trip takes you above it.","cta":"See it worked","level":6,"route":"#/stop/subtract-negative"},"worked-subtract-negative-worked1":{"id":"worked-subtract-negative-worked1","kind":"worked","src":"stop:subtract-negative#worked1","title":"Worked out — Taking away a negative: Below ground, up past 0","body":"−4 − (−9): Taking away −9 is the same as adding → 9 · From −4 up to 0 is → 4 · Still to go after 0: 9 − 4 → 5 · Past zero, so you land on → 5","cta":"Watch it step by step","level":6,"route":"#/stop/subtract-negative"},"idea-subtract-negative-case2":{"id":"idea-subtract-negative-case2","kind":"idea","src":"stop:subtract-negative#case2","title":"Taking away a negative: Below ground, staying there","body":"Still an add, so still going up — but not far enough to reach ground. The answer is negative, just nearer to zero.","cta":"See it worked","level":6,"route":"#/stop/subtract-negative"},"worked-subtract-negative-worked2":{"id":"worked-subtract-negative-worked2","kind":"worked","src":"stop:subtract-negative#worked2","title":"Worked out — Taking away a negative: Below ground, staying there","body":"−9 − (−4): Taking away −4 is the same as adding → 4 · How far below 0 is −9? → 9 · Up 4 brings you closer to 0: 9 − 4 → 5 · Still below zero, so you are at → -5","cta":"Watch it step by step","level":6,"route":"#/stop/subtract-negative"},"why-subtract-negative-why1":{"id":"why-subtract-negative-why1","kind":"why","src":"stop:subtract-negative#why1","title":"Why “Taking away a negative” works","body":"The bank balance says the same thing. A negative number in your account is a bill you owe. If someone takes a bill of 3 away — they pay it for you — you are 3 better off. Taking away a debt is the same as being given money.","cta":"See why","level":6,"route":"#/stop/subtract-negative"},"why-subtract-negative-why2":{"id":"why-subtract-negative-why2","kind":"why","src":"stop:subtract-negative#why2","title":"Why “Taking away a negative” works","body":"So whenever you see “minus a negative”, the two minuses together mean add. −4 − (−9) is −4 + 9: start 4 below ground, go up 9, and you land on level 5.","cta":"See why","level":6,"route":"#/stop/subtract-negative"},"moment-subtract-negative-beat3":{"id":"moment-subtract-negative-beat3","kind":"moment","src":"story:subtract-negative#beat3","badge":{"id":"story","label":"A story"},"title":"The pattern on the board — on the notepad","body":"Kwame: So what must come next, when I take away −1? 5 − (−1) = 6","cta":"Read the story","level":6,"route":"#/stop/subtract-negative"},"moral-subtract-negative-beat5":{"id":"moral-subtract-negative-beat5","kind":"moral","src":"story:subtract-negative#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “The pattern on the board”","body":"The pattern does not stop at zero. Neither does the answer.","cta":"Read the story","level":6,"route":"#/stop/subtract-negative"},"try-subtract-negative-L6":{"id":"try-subtract-negative-L6","kind":"try","level":6,"src":"try:subtract-negative@6/1#0","title":"Taking away a negative — your turn","route":"#/stop/subtract-negative","cta":"Practise this stop","play":{"q":"5 − (−1) = ?","opts":["6","1","7"],"after":"Taking away a negative is the same as adding its size: 5 − (−3) = 5 + 3."}},"trick-divisible-6-11-idea":{"id":"trick-divisible-6-11-idea","kind":"trick","src":"stop:divisible-6-11#idea","title":"Tests for 6 and 11","body":"For 6, it must pass the tests for 2 AND 3. For 11, add alternate digits and subtract the two totals: the number divides by 11 when the difference does. 6 is 2 × 3. A number that splits into twos and also into threes splits into sixes, and one that fails either cannot. So: is it even? Do its digits add to a multiple of 3? Both yes means yes.","cta":"Learn the trick","level":6,"route":"#/stop/divisible-6-11"},"story-divisible-6-11-open":{"id":"story-divisible-6-11-open","kind":"story","src":"story:divisible-6-11#open","badge":{"id":"story","label":"A story"},"title":"Teams of eleven","body":"4,158 children sign up for the district football festival. Can they make teams of exactly 11? — with Kwame and Dax.","art":"art/s-stadium.webp","cta":"Read the story","level":6,"route":"#/stop/divisible-6-11"},"hook-divisible-6-11-hook":{"id":"hook-divisible-6-11-hook","kind":"hook","src":"stop:divisible-6-11#hook","title":"Can you? — Tests for 6 and 11","body":"Is 4,158 divisible by 6? By 11? Two different tricks.","cta":"Find out how","level":6,"route":"#/stop/divisible-6-11"},"idea-divisible-6-11-case0":{"id":"idea-divisible-6-11-case0","kind":"idea","src":"stop:divisible-6-11#case0","title":"Tests for 6 and 11: Divisible by 6","body":"Two tests, and it must pass BOTH: even, and a digit sum in the 3 times table. 2,134 is even, but its digits add to 10.","cta":"See it worked","level":6,"route":"#/stop/divisible-6-11"},"worked-divisible-6-11-worked0":{"id":"worked-divisible-6-11-worked0","kind":"worked","src":"stop:divisible-6-11#worked0","title":"Worked out — Tests for 6 and 11: Divisible by 6","body":"Is 2,134 divisible by 6?: Is 2,134 even? → Yes · Add its digits → 10 · Divisible by 6 needs both: even, and a digit sum in the 3 times table → No","cta":"Watch it step by step","level":6,"route":"#/stop/divisible-6-11"},"idea-divisible-6-11-case1":{"id":"idea-divisible-6-11-case1","kind":"idea","src":"stop:divisible-6-11#case1","title":"Tests for 6 and 11: Divisible by 11","body":"Add every other digit from the right, then the digits you skipped. If the two totals match (or differ by 11, 22…), 11 divides it.","cta":"See it worked","level":6,"route":"#/stop/divisible-6-11"},"worked-divisible-6-11-worked1":{"id":"worked-divisible-6-11-worked1","kind":"worked","src":"stop:divisible-6-11#worked1","title":"Worked out — Tests for 6 and 11: Divisible by 11","body":"Is 4,158 divisible by 11?: Starting with the last digit, add every other digit → 9 · Add the digits you skipped → 9 · The difference between the two totals → 0 · Is 0 0 or in the 11 times table? → Yes","cta":"Watch it step by step","level":6,"route":"#/stop/divisible-6-11"},"why-divisible-6-11-why1":{"id":"why-divisible-6-11-why1","kind":"why","src":"stop:divisible-6-11#why1","title":"Why “Tests for 6 and 11” works","body":"For 11, notice that 10 is one less than 11, 100 is one more than 99, 1000 is one less than 1001 — and 11, 99 and 1001 all divide by 11. So each digit, depending on its place, is \"one more\" or \"one less\" than a multiple of 11. Adding the digits in odd places and taking away the digits in even places adds up exactly those leftovers.","cta":"See why","level":6,"route":"#/stop/divisible-6-11"},"why-divisible-6-11-why2":{"id":"why-divisible-6-11-why2","kind":"why","src":"stop:divisible-6-11#why2","title":"Why “Tests for 6 and 11” works","body":"4,158: from the right, 8 + 1 = 9 and 5 + 4 = 9. The difference is 0, so 4,158 divides by 11 (it is 11 × 378).","cta":"See why","level":6,"route":"#/stop/divisible-6-11"},"algebra-divisible-6-11-alg":{"id":"algebra-divisible-6-11-alg","kind":"algebra","src":"stop:divisible-6-11#alg","title":"The algebra behind “Tests for 6 and 11”","body":"6 | n ⇔ 2 | n and 3 | n ; 11 | n ⇔ 11 | (d₀ − d₁ + d₂ − d₃ …)","cta":"See why","level":6,"route":"#/stop/divisible-6-11"},"moment-divisible-6-11-beat3":{"id":"moment-divisible-6-11-beat3","kind":"moment","src":"story:divisible-6-11#beat3","badge":{"id":"story","label":"A story"},"title":"Teams of eleven — on the notepad","body":"Kwame: Now the ones you skipped: 5 and 4. 5 + 4 = 9","cta":"Read the story","level":6,"route":"#/stop/divisible-6-11"},"moral-divisible-6-11-beat5":{"id":"moral-divisible-6-11-beat5","kind":"moral","src":"story:divisible-6-11#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Teams of eleven”","body":"A difference of 0 means 11 divides it.","cta":"Read the story","level":6,"route":"#/stop/divisible-6-11"},"try-divisible-6-11-L6":{"id":"try-divisible-6-11-L6","kind":"try","level":6,"src":"try:divisible-6-11@6/1#0","title":"Tests for 6 and 11 — your turn","route":"#/stop/divisible-6-11","cta":"Practise this stop","play":{"q":"Is 4,479 divisible by 6?","opts":["No","Yes"],"after":"For 6, it must pass the tests for 2 AND 3. For 11, add alternate digits and subtract the two totals: the number divides by 11 when the difference does."}},"trick-factor-tree-idea":{"id":"trick-factor-tree-idea","kind":"trick","src":"stop:factor-tree#idea","title":"Factor trees","body":"Split the number into two factors, then split those, until every branch ends in a prime. Primes are the atoms of multiplication: every whole number bigger than 1 is either prime or can be broken into smaller factors, and those into smaller ones again. The breaking has to stop, because the numbers keep getting smaller — and it stops at primes, which cannot be broken.","cta":"Learn the trick","level":6,"route":"#/stop/factor-tree"},"story-factor-tree-open":{"id":"story-factor-tree-open","kind":"story","src":"story:factor-tree#open","badge":{"id":"story","label":"A story"},"title":"The family tree of 84","body":"Rafi carves 84 at the top of a trail sign and draws two branches under it. — with Rafi and Nova.","art":"art/s-forest.webp","cta":"Read the story","level":6,"route":"#/stop/factor-tree"},"hook-factor-tree-hook":{"id":"hook-factor-tree-hook","kind":"hook","src":"stop:factor-tree#hook","title":"Can you? — Factor trees","body":"84 — which primes multiply to make it?","cta":"Find out how","level":6,"route":"#/stop/factor-tree"},"idea-factor-tree-case0":{"id":"idea-factor-tree-case0","kind":"idea","src":"stop:factor-tree#case0","title":"Factor trees: The largest prime factor","body":"Break the number down until every branch ends in a prime, then pick the biggest prime at the ends.","cta":"See it worked","level":6,"route":"#/stop/factor-tree"},"worked-factor-tree-worked0":{"id":"worked-factor-tree-worked0","kind":"worked","src":"stop:factor-tree#worked0","title":"Worked out — Factor trees: The largest prime factor","body":"What is the largest prime factor of 84?: 84 = 2 × ? → 42 · 42 = 2 × ? → 21 · 21 = 3 × ? → 7 · The largest prime at the ends of the branches → 7","cta":"Watch it step by step","level":6,"route":"#/stop/factor-tree"},"idea-factor-tree-case1":{"id":"idea-factor-tree-case1","kind":"idea","src":"stop:factor-tree#case1","title":"Factor trees: How many primes","body":"Count every prime at the ends of the branches, repeats included: 72 = 2 × 2 × 2 × 3 × 3 is five primes, not two.","cta":"See it worked","level":6,"route":"#/stop/factor-tree"},"worked-factor-tree-worked1":{"id":"worked-factor-tree-worked1","kind":"worked","src":"stop:factor-tree#worked1","title":"Worked out — Factor trees: How many primes","body":"Write 72 as a product of primes. How many primes are multiplied, counting repeats?: 72 = 2 × ? → 36 · 36 = 2 × ? → 18 · 18 = 2 × ? → 9 · 9 = 3 × ? → 3 · Count the primes at the ends of the branches → 5","cta":"Watch it step by step","level":6,"route":"#/stop/factor-tree"},"why-factor-tree-why1":{"id":"why-factor-tree-why1","kind":"why","src":"stop:factor-tree#why1","title":"Why “Factor trees” works","body":"84 splits as 2 × 42, then 42 as 2 × 21, then 21 as 3 × 7. The ends of the branches are 2, 2, 3 and 7, and 2 × 2 × 3 × 7 = 84.","cta":"See why","level":6,"route":"#/stop/factor-tree"},"why-factor-tree-why2":{"id":"why-factor-tree-why2","kind":"why","src":"stop:factor-tree#why2","title":"Why “Factor trees” works","body":"The surprising part: however you split — 84 = 4 × 21 or 12 × 7 — the branches always end in the same primes. Every number has exactly one set of prime factors, like a fingerprint. That is why the prime factors are called the number's building blocks.","cta":"See why","level":6,"route":"#/stop/factor-tree"},"algebra-factor-tree-alg":{"id":"algebra-factor-tree-alg","kind":"algebra","src":"stop:factor-tree#alg","title":"The algebra behind “Factor trees”","body":"n = p₁ × p₂ × … × pₖ, the same primes however you split","cta":"See why","level":6,"route":"#/stop/factor-tree"},"moment-factor-tree-beat2":{"id":"moment-factor-tree-beat2","kind":"moment","src":"story:factor-tree#beat2","badge":{"id":"story","label":"A story"},"title":"The family tree of 84 — on the notepad","body":"Nova: 42 is even too: another 2. 42 ÷ 2 = 21","cta":"Read the story","level":6,"route":"#/stop/factor-tree"},"moral-factor-tree-beat5":{"id":"moral-factor-tree-beat5","kind":"moral","src":"story:factor-tree#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The family tree of 84”","body":"Split it any way you like — the ends are always 2, 2, 3 and 7.","cta":"Read the story","level":6,"route":"#/stop/factor-tree"},"try-factor-tree-L6":{"id":"try-factor-tree-L6","kind":"try","level":6,"src":"try:factor-tree@6/1#0","title":"Factor trees — your turn","route":"#/stop/factor-tree","cta":"Practise this stop","play":{"q":"What is the largest prime factor of 35?","opts":["7","8","6"],"after":"Split the number into two factors, then split those, until every branch ends in a prime."}},"trick-hcf-idea":{"id":"trick-hcf-idea","kind":"trick","src":"stop:hcf#idea","title":"Highest common factor","body":"Divide both numbers by a prime they share, again and again, until nothing is shared. Multiply the primes you took out. A common factor divides both numbers. The highest one is useful whenever you want to cut two things into equal pieces with none left over — or to simplify a fraction in one go: 24/36 becomes 2/3 when you divide top and bottom by 12.","cta":"Learn the trick","level":6,"route":"#/stop/hcf"},"story-hcf-open":{"id":"story-hcf-open","kind":"story","src":"story:hcf#open","badge":{"id":"story","label":"A story"},"title":"Sharing the fruit","body":"Ines has 24 oranges and 36 apples to pack into identical bags, with nothing left over. What is the most bags she can fill? — with Ines and Suki.","art":"art/s-kitchen.webp","cta":"Read the story","level":6,"route":"#/stop/hcf"},"hook-hcf-hook":{"id":"hook-hcf-hook","kind":"hook","src":"stop:hcf#hook","title":"Can you? — Highest common factor","body":"24 and 36 — what is the biggest number that divides both?","cta":"Find out how","level":6,"route":"#/stop/hcf"},"worked-hcf-worked0":{"id":"worked-hcf-worked0","kind":"worked","src":"stop:hcf#worked0","title":"Worked out — Highest common factor","body":"HCF of 24 and 36: 24 and 36: the smallest prime that divides both → 2 · 12 and 18: the smallest prime that divides both → 2 · 6 and 9: the smallest prime that divides both → 3 · No prime divides both 2 and 3. Multiply the primes you took out: 2 × 2 × 3 → 12","cta":"Watch it step by step","level":6,"route":"#/stop/hcf"},"why-hcf-why1":{"id":"why-hcf-why1","kind":"why","src":"stop:hcf#why1","title":"Why “Highest common factor” works","body":"Every factor of a number is made from its primes. 24 is 2 × 2 × 2 × 3 and 36 is 2 × 2 × 3 × 3. Any number that divides both can only use primes that both of them have, as many times as both have them: two 2s and one 3. The most you can take is all of those together: 2 × 2 × 3 = 12.","cta":"See why","level":6,"route":"#/stop/hcf"},"why-hcf-why2":{"id":"why-hcf-why2","kind":"why","src":"stop:hcf#why2","title":"Why “Highest common factor” works","body":"Dividing both numbers by a shared prime, over and over, takes out exactly those shared primes, one at a time. When the two leftovers share nothing, you have taken them all.","cta":"See why","level":6,"route":"#/stop/hcf"},"algebra-hcf-alg":{"id":"algebra-hcf-alg","kind":"algebra","src":"stop:hcf#alg","title":"The algebra behind “Highest common factor”","body":"HCF(a, b) = product of the primes a and b share (with repeats)","cta":"See why","level":6,"route":"#/stop/hcf"},"moment-hcf-beat2":{"id":"moment-hcf-beat2","kind":"moment","src":"story:hcf#beat2","badge":{"id":"story","label":"A story"},"title":"Sharing the fruit — on the notepad","body":"Ines: 12 and 18. Still both even. Halve again: 6 and 9. 12 ÷ 2 = 6","cta":"Read the story","level":6,"route":"#/stop/hcf"},"moral-hcf-beat5":{"id":"moral-hcf-beat5","kind":"moral","src":"story:hcf#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “Sharing the fruit”","body":"Twelve bags, each with 2 oranges and 3 apples.","cta":"Read the story","level":6,"route":"#/stop/hcf"},"try-hcf-L6":{"id":"try-hcf-L6","kind":"try","level":6,"src":"try:hcf@6/1#0","title":"Highest common factor — your turn","route":"#/stop/hcf","cta":"Practise this stop","play":{"q":"HCF of 36 and 42 = ?","opts":["6","2","3"],"after":"Divide both numbers by a prime they share, again and again, until nothing is shared. Multiply the primes you took out."}},"trick-lcm-idea":{"id":"trick-lcm-idea","kind":"trick","src":"stop:lcm#idea","title":"Lowest common multiple","body":"Divide one number by the highest common factor, then multiply by the other. The first bus leaves at 6, 12, 18, 24… minutes; the second at 8, 16, 24… They meet again at the first number in both lists — the lowest common multiple. You could write out both lists, but there is a shortcut.","cta":"Learn the trick","level":6,"route":"#/stop/lcm"},"story-lcm-open":{"id":"story-lcm-open","kind":"story","src":"story:lcm#open","badge":{"id":"story","label":"A story"},"title":"The two buses","body":"The number 6 bus comes every 6 minutes and the number 8 bus every 8. Both have just left the stop. — with Theo and Pip.","art":"art/s-bus.webp","cta":"Read the story","level":6,"route":"#/stop/lcm"},"hook-lcm-hook":{"id":"hook-lcm-hook","kind":"hook","src":"stop:lcm#hook","title":"Can you? — Lowest common multiple","body":"One bus comes every 6 minutes, another every 8. They have just left together. When do they next leave together?","cta":"Find out how","level":6,"route":"#/stop/lcm"},"idea-lcm-case0":{"id":"idea-lcm-case0","kind":"idea","src":"stop:lcm#case0","title":"Lowest common multiple: They share a factor","body":"Multiplying the two counts the shared factor twice, so divide it out once first: 6 ÷ 2 × 8.","cta":"See it worked","level":6,"route":"#/stop/lcm"},"worked-lcm-worked0":{"id":"worked-lcm-worked0","kind":"worked","src":"stop:lcm#worked0","title":"Worked out — Lowest common multiple: They share a factor","body":"One bus comes every 6 minutes, another every 8. They leave together. How many minutes until they next leave together?: HCF of 6 and 8 → 2 · 6 ÷ 2 → 3 · 3 × 8 → 24","cta":"Watch it step by step","level":6,"route":"#/stop/lcm"},"idea-lcm-case1":{"id":"idea-lcm-case1","kind":"idea","src":"stop:lcm#case1","title":"Lowest common multiple: They share nothing","body":"When the HCF is 1 there is nothing to take out, so the LCM is simply the two numbers multiplied.","cta":"See it worked","level":6,"route":"#/stop/lcm"},"worked-lcm-worked1":{"id":"worked-lcm-worked1","kind":"worked","src":"stop:lcm#worked1","title":"Worked out — Lowest common multiple: They share nothing","body":"Two lights flash together. One flashes every 4 seconds, the other every 9. After how many seconds do they next flash together?: HCF of 4 and 9 → 1 · 4 ÷ 1 → 4 · 4 × 9 → 36","cta":"Watch it step by step","level":6,"route":"#/stop/lcm"},"why-lcm-why1":{"id":"why-lcm-why1","kind":"why","src":"stop:lcm#why1","title":"Why “Lowest common multiple” works","body":"6 × 8 = 48 is certainly a time they both leave, but it is not the first: 6 and 8 share a factor of 2, so multiplying them counts that 2 twice. Take it out once — 48 ÷ 2 = 24 — and you have the smallest number both divide. Doing it as 6 ÷ 2 × 8 keeps the numbers small.","cta":"See why","level":6,"route":"#/stop/lcm"},"why-lcm-why2":{"id":"why-lcm-why2","kind":"why","src":"stop:lcm#why2","title":"Why “Lowest common multiple” works","body":"In primes: 6 = 2 × 3 and 8 = 2 × 2 × 2. A common multiple must contain everything in each: three 2s and a 3. The fewest you can use is exactly that, 2 × 2 × 2 × 3 = 24. When two numbers share nothing, like 4 and 9, the LCM is just their product.","cta":"See why","level":6,"route":"#/stop/lcm"},"algebra-lcm-alg":{"id":"algebra-lcm-alg","kind":"algebra","src":"stop:lcm#alg","title":"The algebra behind “Lowest common multiple”","body":"LCM(a, b) = a ÷ HCF(a, b) × b","cta":"See why","level":6,"route":"#/stop/lcm"},"moment-lcm-beat4":{"id":"moment-lcm-beat4","kind":"moment","src":"story:lcm#beat4","badge":{"id":"story","label":"A story"},"title":"The two buses — on the notepad","body":"Theo: 6 and 8 share a factor of 2, so multiplying counts it twice. Take it out once. 48 ÷ 2 = 24","cta":"Read the story","level":6,"route":"#/stop/lcm"},"moral-lcm-beat5":{"id":"moral-lcm-beat5","kind":"moral","src":"story:lcm#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The two buses”","body":"Or 6 ÷ 2, then times 8 — smaller numbers.","cta":"Read the story","level":6,"route":"#/stop/lcm"},"try-lcm-L6":{"id":"try-lcm-L6","kind":"try","level":6,"src":"try:lcm@6/1#0","title":"Lowest common multiple — your turn","route":"#/stop/lcm","cta":"Practise this stop","play":{"q":"One bus comes every 10 minutes, another every 7. They leave together. How many minutes until they next leave together?","opts":["70","1","10"],"after":"Divide one number by the highest common factor, then multiply by the other."}},"trick-prime-stones-idea":{"id":"trick-prime-stones-idea","kind":"trick","src":"stop:prime-stones#idea","title":"Building with prime stones","body":"Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide. A prime is a number bigger than 1 that cannot be split into smaller whole-number factors: 2, 3, 5, 7, 11… Every other number bigger than 1 can be split, and split again, until only primes are left. So the primes are the stones every number is built from.","cta":"Learn the trick","level":6,"route":"#/stop/prime-stones"},"story-prime-stones-open":{"id":"story-prime-stones-open","kind":"story","src":"story:prime-stones#open","badge":{"id":"story","label":"A story"},"title":"Towers of stones","body":"Rafi and Nova build number towers. The rule: only prime stones — 2, 3, 5, 7 and so on. — with Rafi and Nova.","art":"art/s-city.webp","cta":"Read the story","level":6,"route":"#/stop/prime-stones"},"idea-prime-stones-case0":{"id":"idea-prime-stones-case0","kind":"idea","src":"stop:prime-stones#case0","title":"Building with prime stones: Build the number","body":"Multiply the stones one at a time, carrying the answer along: 2 × 2, then × 3, then × 5.","cta":"See it worked","level":6,"route":"#/stop/prime-stones"},"idea-prime-stones-case1":{"id":"idea-prime-stones-case1","kind":"idea","src":"stop:prime-stones#case1","title":"Building with prime stones: Find the missing stone","body":"Backwards: multiply the stones you can see, then divide the number by that. What is left is the one missing prime.","cta":"See it worked","level":6,"route":"#/stop/prime-stones"},"why-prime-stones-why1":{"id":"why-prime-stones-why1","kind":"why","src":"stop:prime-stones#why1","title":"Why “Building with prime stones” works","body":"60 is built from 2, 2, 3 and 5. You can multiply them in any order — 2 × 2 is 4, 4 × 3 is 12, 12 × 5 is 60 — because the order of multiplying never changes the answer.","cta":"See why","level":6,"route":"#/stop/prime-stones"},"algebra-prime-stones-alg":{"id":"algebra-prime-stones-alg","kind":"algebra","src":"stop:prime-stones#alg","title":"The algebra behind “Building with prime stones”","body":"every n > 1 = p₁ × p₂ × … × pₖ, one way only (apart from order)","cta":"See why","level":6,"route":"#/stop/prime-stones"},"moral-prime-stones-beat5":{"id":"moral-prime-stones-beat5","kind":"moral","src":"story:prime-stones#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “Towers of stones”","body":"Every number has exactly one set of prime stones. Only the order can change.","cta":"Read the story","level":6,"route":"#/stop/prime-stones"},"try-prime-stones-L6":{"id":"try-prime-stones-L6","kind":"try","level":6,"src":"try:prime-stones@6/1#0","title":"Building with prime stones — your turn","route":"#/stop/prime-stones","cta":"Practise this stop","play":{"q":"3 × 3 × 5 = ?","opts":["45","9","46"],"after":"Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide."}},"hook-square-dots-hook":{"id":"hook-square-dots-hook","kind":"hook","src":"stop:square-dots#hook","title":"Can you? — What a square number is","body":"7² — why is 49 called a SQUARE number?","cta":"Find out how","level":6,"route":"#/stop/square-dots"},"why-square-dots-why1":{"id":"why-square-dots-why1","kind":"why","src":"stop:square-dots#why1","title":"Why “What a square number is” works","body":"That is where the name comes from: a square number is a number of dots that can stand in a perfect square, with nothing left over. 12 cannot — 3 rows of 4 is a rectangle, not a square — but 16 can, as 4 rows of 4.","cta":"See why","level":6,"route":"#/stop/square-dots"},"algebra-square-dots-alg":{"id":"algebra-square-dots-alg","kind":"algebra","src":"stop:square-dots#alg","title":"The algebra behind “What a square number is”","body":"n² = n × n","cta":"See why","level":6,"route":"#/stop/square-dots"},"moral-square-dots-beat5":{"id":"moral-square-dots-beat5","kind":"moral","src":"story:square-dots#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The parade ground”","body":"So this morning there are forty-nine guards. Forty-nine is a square number!","cta":"Read the story","level":6,"route":"#/stop/square-dots"},"try-square-dots-L6":{"id":"try-square-dots-L6","kind":"try","level":6,"src":"try:square-dots@6/2#0","title":"What a square number is — your turn","route":"#/stop/square-dots","cta":"Practise this stop","play":{"q":"12² = ?","opts":["144","12","145"],"after":"n² means n rows of n. Lay them out and they make a perfect square."}},"trick-teen-squares-idea":{"id":"trick-teen-squares-idea","kind":"trick","src":"stop:teen-squares#idea","title":"Every square to 20","body":"Split 13 into 10 and 3. The square is 10², plus two 10-by-3 strips, plus 3². Draw a square 13 wide. Cut it 10 along each side. You get four pieces: a 10-by-10 square (100), two strips 10 by 3 (30 each), and a little 3-by-3 corner (9). Together: 100 + 60 + 9 = 169.","cta":"Learn the trick","level":6,"route":"#/stop/teen-squares"},"story-teen-squares-open":{"id":"story-teen-squares-open","kind":"story","src":"story:teen-squares#open","badge":{"id":"story","label":"A story"},"title":"The carpet in the hall","body":"The palace needs a square carpet for the throne room, 13 tiles along each side. How many tiles? — with Mira and Rafi.","art":"art/s-palace.webp","cta":"Read the story","level":6,"route":"#/stop/teen-squares"},"hook-teen-squares-hook":{"id":"hook-teen-squares-hook","kind":"hook","src":"stop:teen-squares#hook","title":"Can you? — Every square to 20","body":"13² — without multiplying 13 by 13.","cta":"Find out how","level":6,"route":"#/stop/teen-squares"},"worked-teen-squares-worked0":{"id":"worked-teen-squares-worked0","kind":"worked","src":"stop:teen-squares#worked0","title":"Worked out — Every square to 20","body":"13²: The big square: 10² → 100 · Two strips: 2 × 10 × 3 → 60 · The corner: 3² → 9 · 100 + 60 + 9 → 169","cta":"Watch it step by step","level":6,"route":"#/stop/teen-squares"},"why-teen-squares-why1":{"id":"why-teen-squares-why1","kind":"why","src":"stop:teen-squares#why1","title":"Why “Every square to 20” works","body":"That is why every teen square is so quick: it is always 100, plus 20 lots of the ones digit, plus the ones digit squared. 17² = 100 + 140 + 49 = 289. Say it five times and the squares to 20 are yours for life.","cta":"See why","level":6,"route":"#/stop/teen-squares"},"why-teen-squares-why2":{"id":"why-teen-squares-why2","kind":"why","src":"stop:teen-squares#why2","title":"Why “Every square to 20” works","body":"The same picture works for any number split into two parts, a and b: the big square a², two strips a × b, and the corner b². 34² = 900 + 240 + 16 = 1156. Mathematicians write it (a + b)² = a² + 2ab + b².","cta":"See why","level":6,"route":"#/stop/teen-squares"},"algebra-teen-squares-alg":{"id":"algebra-teen-squares-alg","kind":"algebra","src":"stop:teen-squares#alg","title":"The algebra behind “Every square to 20”","body":"(a + b)² = a² + 2ab + b²   ·   (10 + b)² = 100 + 20b + b²","cta":"See why","level":6,"route":"#/stop/teen-squares"},"moment-teen-squares-beat3":{"id":"moment-teen-squares-beat3","kind":"moment","src":"story:teen-squares#beat3","badge":{"id":"story","label":"A story"},"title":"The carpet in the hall — on the notepad","body":"Rafi: …two long strips, 10 by 3, down two sides… 2 × 10 × 3 = 60","cta":"Read the story","level":6,"route":"#/stop/teen-squares"},"moral-teen-squares-beat5":{"id":"moral-teen-squares-beat5","kind":"moral","src":"story:teen-squares#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The carpet in the hall”","body":"One hundred and sixty-nine. Every teen square is 100, plus two strips, plus a corner.","cta":"Read the story","level":6,"route":"#/stop/teen-squares"},"try-teen-squares-L6":{"id":"try-teen-squares-L6","kind":"try","level":6,"src":"try:teen-squares@6/1#0","title":"Every square to 20 — your turn","route":"#/stop/teen-squares","cta":"Practise this stop","play":{"q":"14² = ?","opts":["196","100","80"],"after":"Split 13 into 10 and 3. The square is 10², plus two 10-by-3 strips, plus 3²."}},"trick-root-of-square-idea":{"id":"trick-root-of-square-idea","kind":"trick","src":"stop:root-of-square#idea","title":"Square roots","body":"The square root undoes squaring. Find the tens digit from 10² and 20², then the ones digit from the last digit. If 14 × 14 = 196, then the square root of 196 is 14: √196 = 14. The root is the side of the square; the square number is how many dots fill it.","cta":"Learn the trick","level":6,"route":"#/stop/root-of-square"},"story-root-of-square-open":{"id":"story-root-of-square-open","kind":"story","src":"story:root-of-square#open","badge":{"id":"story","label":"A story"},"title":"The square courtyard","body":"A square courtyard is paved with 196 stones. Suki wants to know how many stones long each side is. — with Mira and Suki.","art":"art/s-palace.webp","cta":"Read the story","level":6,"route":"#/stop/root-of-square"},"hook-root-of-square-hook":{"id":"hook-root-of-square-hook","kind":"hook","src":"stop:root-of-square#hook","title":"Can you? — Square roots","body":"√196 — which number times itself makes 196?","cta":"Find out how","level":6,"route":"#/stop/root-of-square"},"idea-root-of-square-case0":{"id":"idea-root-of-square-case0","kind":"idea","src":"stop:root-of-square#case0","title":"Square roots: An exact square root","body":"The tens digit comes from which squares of 10 it sits between; the ones digit from its last digit. Then check.","cta":"See it worked","level":6,"route":"#/stop/root-of-square"},"worked-root-of-square-worked0":{"id":"worked-root-of-square-worked0","kind":"worked","src":"stop:root-of-square#worked0","title":"Worked out — Square roots: An exact square root","body":"√196: Tens digit of the root (10² = 100, 20² = 400) → 1 · Ones digit of the root: which digit, squared, ends in 6? (then check) → 4 · So √196 → 14","cta":"Watch it step by step","level":6,"route":"#/stop/root-of-square"},"idea-root-of-square-case1":{"id":"idea-root-of-square-case1","kind":"idea","src":"stop:root-of-square#case1","title":"Square roots: Between two whole numbers","body":"Not a perfect square, so the root is not whole. Find the biggest square that is not over it — its root is the smaller neighbour.","cta":"See it worked","level":6,"route":"#/stop/root-of-square"},"worked-root-of-square-worked1":{"id":"worked-root-of-square-worked1","kind":"worked","src":"stop:root-of-square#worked1","title":"Worked out — Square roots: Between two whole numbers","body":"√200 is between two whole numbers. Type the smaller one.: The biggest square not over 200 → 196 · Its root → 14","cta":"Watch it step by step","level":6,"route":"#/stop/root-of-square"},"why-root-of-square-why1":{"id":"why-root-of-square-why1","kind":"why","src":"stop:root-of-square#why1","title":"Why “Square roots” works","body":"196 is between 100 (10²) and 400 (20²), so its root is between 10 and 20 — the tens digit is 1. It ends in 6, and only numbers ending in 4 or 6 have squares ending in 6. 14² = 196. Done.","cta":"See why","level":6,"route":"#/stop/root-of-square"},"why-root-of-square-why2":{"id":"why-root-of-square-why2","kind":"why","src":"stop:root-of-square#why2","title":"Why “Square roots” works","body":"Most numbers are not perfect squares, and their roots are not whole. √200 is a little more than 14, because 14² = 196 is just under 200 and 15² = 225 is over it. So √200 lies between 14 and 15 — and that is often all you need to know.","cta":"See why","level":6,"route":"#/stop/root-of-square"},"algebra-root-of-square-alg":{"id":"algebra-root-of-square-alg","kind":"algebra","src":"stop:root-of-square#alg","title":"The algebra behind “Square roots”","body":"√(n²) = n   ·   a² ≤ x < (a + 1)² ⇒ a ≤ √x < a + 1","cta":"See why","level":6,"route":"#/stop/root-of-square"},"moment-root-of-square-beat4":{"id":"moment-root-of-square-beat4","kind":"moment","src":"story:root-of-square#beat4","badge":{"id":"story","label":"A story"},"title":"The square courtyard — on the notepad","body":"Mira: Then try 14 and 16. 14 × 14 is just right. 14 × 14 = 196","cta":"Read the story","level":6,"route":"#/stop/root-of-square"},"moral-root-of-square-beat5":{"id":"moral-root-of-square-beat5","kind":"moral","src":"story:root-of-square#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The square courtyard”","body":"Fourteen stones a side. The square root undoes the square.","cta":"Read the story","level":6,"route":"#/stop/root-of-square"},"try-root-of-square-L6":{"id":"try-root-of-square-L6","kind":"try","level":6,"src":"try:root-of-square@6/1#0","title":"Square roots — your turn","route":"#/stop/root-of-square","cta":"Practise this stop","play":{"q":"√25 = ?","opts":["5","0","6"],"after":"The square root undoes squaring. Find the tens digit from 10² and 20², then the ones digit from the last digit."}},"hook-mean-fair-share-hook":{"id":"hook-mean-fair-share-hook","kind":"hook","src":"stop:mean-fair-share#hook","title":"Can you? — The mean: fair shares","body":"Four friends won 3, 7, 5 and 9 tickets. If they share them out fairly, how many each?","cta":"Find out how","level":6,"route":"#/stop/mean-fair-share"},"why-mean-fair-share-why1":{"id":"why-mean-fair-share-why1","kind":"why","src":"stop:mean-fair-share#why1","title":"Why “The mean: fair shares” works","body":"Picture it as towers of blocks: the mean is what you get when you knock the tall towers down and use the spare blocks to build up the short ones until all the towers are level.","cta":"See why","level":6,"route":"#/stop/mean-fair-share"},"algebra-mean-fair-share-alg":{"id":"algebra-mean-fair-share-alg","kind":"algebra","src":"stop:mean-fair-share#alg","title":"The algebra behind “The mean: fair shares”","body":"mean = (x₁ + x₂ + … + xₙ) ÷ n","cta":"See why","level":6,"route":"#/stop/mean-fair-share"},"moral-mean-fair-share-beat4":{"id":"moral-mean-fair-share-beat4","kind":"moral","src":"story:mean-fair-share#beat4","badge":{"id":"story","label":"A story"},"title":"Nova, in “Sharing the tickets”","body":"Suki gave up 3, I gained 3 — it all levels out.","cta":"Read the story","level":6,"route":"#/stop/mean-fair-share"},"try-mean-fair-share-L6":{"id":"try-mean-fair-share-L6","kind":"try","level":6,"src":"try:mean-fair-share@6/2#0","title":"The mean: fair shares — your turn","route":"#/stop/mean-fair-share","cta":"Practise this stop","play":{"q":"The mean of 5, 10, 19, 14 = ?","opts":["12","48","4"],"after":"Add everything up, then share it out equally: divide by how many numbers there are."}},"trick-median-mode-idea":{"id":"trick-median-mode-idea","kind":"trick","src":"stop:median-mode#idea","title":"Median and mode","body":"The median is the middle number once they are in order. The mode is the number that turns up most. The median is a middle, so it only makes sense once the numbers stand in a line from smallest to largest. Then half of them are on one side and half on the other — like the child in the middle of a line-up by height.","cta":"Learn the trick","level":6,"route":"#/stop/median-mode"},"story-median-mode-open":{"id":"story-median-mode-open","kind":"story","src":"story:median-mode#open","badge":{"id":"story","label":"A story"},"title":"The coconut shy","body":"Five throws at the coconut shy score 12, 5, 9, 14 and 7 points. Ines wants the middle score. — with Theo and Ines.","art":"art/s-fair.webp","cta":"Read the story","level":6,"route":"#/stop/median-mode"},"hook-median-mode-hook":{"id":"hook-median-mode-hook","kind":"hook","src":"stop:median-mode#hook","title":"Can you? — Median and mode","body":"Seven scores, all jumbled. Which one is right in the middle?","cta":"Find out how","level":6,"route":"#/stop/median-mode"},"idea-median-mode-case0":{"id":"idea-median-mode-case0","kind":"idea","src":"stop:median-mode#case0","title":"Median and mode: Median","body":"Put them in order first. With an odd count there is one number right in the middle.","cta":"See it worked","level":6,"route":"#/stop/median-mode"},"worked-median-mode-worked0":{"id":"worked-median-mode-worked0","kind":"worked","src":"stop:median-mode#worked0","title":"Worked out — Median and mode: Median","body":"The median of 12, 5, 9, 14, 7: How many numbers? → 5 · Which place in the line is the middle? → 3 · Put them in order and read that one → 9","cta":"Watch it step by step","level":6,"route":"#/stop/median-mode"},"idea-median-mode-case1":{"id":"idea-median-mode-case1","kind":"idea","src":"stop:median-mode#case1","title":"Median and mode: Median of an even count","body":"With an even count, two numbers share the middle. The median is halfway between them.","cta":"See it worked","level":6,"route":"#/stop/median-mode"},"worked-median-mode-worked1":{"id":"worked-median-mode-worked1","kind":"worked","src":"stop:median-mode#worked1","title":"Worked out — Median and mode: Median of an even count","body":"The median of 12, 5, 9, 14, 7, 3: In order, the first of the two middle numbers → 7 · and the second → 9 · Halfway between them → 8","cta":"Watch it step by step","level":6,"route":"#/stop/median-mode"},"idea-median-mode-case2":{"id":"idea-median-mode-case2","kind":"idea","src":"stop:median-mode#case2","title":"Median and mode: Mode","body":"No ordering needed: the mode is simply the number that turns up most often.","cta":"See it worked","level":6,"route":"#/stop/median-mode"},"worked-median-mode-worked2":{"id":"worked-median-mode-worked2","kind":"worked","src":"stop:median-mode#worked2","title":"Worked out — Median and mode: Mode","body":"The mode of 4, 7, 4, 2, 9, 4: How many times does the most common number appear? → 3 · Which number is it? → 4","cta":"Watch it step by step","level":6,"route":"#/stop/median-mode"},"why-median-mode-why1":{"id":"why-median-mode-why1","kind":"why","src":"stop:median-mode#why1","title":"Why “Median and mode” works","body":"With an even count there are two middle numbers, and the median is halfway between them — the point that still splits the line into two equal halves.","cta":"See why","level":6,"route":"#/stop/median-mode"},"why-median-mode-why2":{"id":"why-median-mode-why2","kind":"why","src":"stop:median-mode#why2","title":"Why “Median and mode” works","body":"The mode is the most popular: the number you see most often. It is the only \"average\" that works for things that are not numbers at all — the favourite ride, the most common colour.","cta":"See why","level":6,"route":"#/stop/median-mode"},"algebra-median-mode-alg":{"id":"algebra-median-mode-alg","kind":"algebra","src":"stop:median-mode#alg","title":"The algebra behind “Median and mode”","body":"median = the ((n + 1) ÷ 2)th value in order · mode = the most frequent value","cta":"See why","level":6,"route":"#/stop/median-mode"},"moment-median-mode-beat3":{"id":"moment-median-mode-beat3","kind":"moment","src":"story:median-mode#beat3","badge":{"id":"story","label":"A story"},"title":"The coconut shy — on the notepad","body":"Ines: Five scores, so the middle is the third one. (5 + 1) ÷ 2 = 3","cta":"Read the story","level":6,"route":"#/stop/median-mode"},"moral-median-mode-beat5":{"id":"moral-median-mode-beat5","kind":"moral","src":"story:median-mode#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The coconut shy”","body":"The median is 9. Order first, then find the middle.","cta":"Read the story","level":6,"route":"#/stop/median-mode"},"try-median-mode-L6":{"id":"try-median-mode-L6","kind":"try","level":6,"src":"try:median-mode@6/1#0","title":"Median and mode — your turn","route":"#/stop/median-mode","cta":"Practise this stop","play":{"q":"The median of 15, 9, 7, 8, 12 = ?","opts":["9","5","3"],"after":"The median is the middle number once they are in order. The mode is the number that turns up most."}},"hook-data-range-hook":{"id":"hook-data-range-hook","kind":"hook","src":"stop:data-range#hook","title":"Can you? — The range: how spread out?","body":"Scores of 14, 31, 25, 9 and 27. How far apart is the best from the worst?","cta":"Find out how","level":6,"route":"#/stop/data-range"},"why-data-range-why1":{"id":"why-data-range-why1","kind":"why","src":"stop:data-range#why1","title":"Why “The range: how spread out?” works","body":"The range is the distance from the lowest number to the highest — the whole width the data is spread across, like the length of a line from the shortest child to the tallest.","cta":"See why","level":6,"route":"#/stop/data-range"},"algebra-data-range-alg":{"id":"algebra-data-range-alg","kind":"algebra","src":"stop:data-range#alg","title":"The algebra behind “The range: how spread out?”","body":"range = largest − smallest","cta":"See why","level":6,"route":"#/stop/data-range"},"moral-data-range-beat5":{"id":"moral-data-range-beat5","kind":"moral","src":"story:data-range#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Two cricket teams”","body":"A range of 22 runs.","cta":"Read the story","level":6,"route":"#/stop/data-range"},"try-data-range-L6":{"id":"try-data-range-L6","kind":"try","level":6,"src":"try:data-range@6/2#0","title":"The range: how spread out? — your turn","route":"#/stop/data-range","cta":"Practise this stop","play":{"q":"The range of 28, 9, 57, 17, 14, 46 = ?","opts":["48","57","9"],"after":"Find the largest and the smallest, and take one from the other."}},"word-exterior-angle":{"id":"word-exterior-angle","kind":"word","src":"dictionary:exterior angle#def","title":"exterior angle","body":"The turn you make at a corner as you walk round the outside of a shape. For example: Regular hexagon: 360° ÷ 6 = 60° at each corner.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-exterior-angle":{"id":"wordq-exterior-angle","kind":"wordq","src":"dictionary:exterior angle#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Regular hexagon: 360° ÷ 6 = 60° at each corner.”","opts":["exterior angle","subset","lowest common multiple"],"after":"exterior angle: The turn you make at a corner as you walk round the outside of a shape."},"level":6},"word-factor-tree":{"id":"word-factor-tree","kind":"word","src":"dictionary:factor tree#def","title":"factor tree","body":"A branching drawing that splits a number into two factors, again and again, until every branch ends in a prime. For example: 60 → 6 × 10 → 2 × 3 × 2 × 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-factor-tree":{"id":"wordq-factor-tree","kind":"wordq","src":"dictionary:factor tree#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “60 → 6 × 10 → 2 × 3 × 2 × 5.”","opts":["factor tree","digit root","analogue clock"],"after":"factor tree: A branching drawing that splits a number into two factors, again and again, until every branch ends in a prime."},"level":6},"word-factorise":{"id":"word-factorise","kind":"word","src":"dictionary:factorise#def","title":"factorise","body":"Put an expression back into brackets by taking out a factor that every part shares. For example: 6x + 9 = 3(2x + 3).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-factorise":{"id":"wordq-factorise","kind":"wordq","src":"dictionary:factorise#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “6x + 9 = 3(2x + 3).”","opts":["factorise","zero","arrangement"],"after":"factorise: Put an expression back into brackets by taking out a factor that every part shares."},"level":6},"word-highest-common-factor":{"id":"word-highest-common-factor","kind":"word","src":"dictionary:highest common factor#def","title":"highest common factor","body":"The biggest whole number that divides exactly into two or more numbers. Short name: HCF. For example: For 12 and 18 it is 6.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-highest-common-factor":{"id":"wordq-highest-common-factor","kind":"wordq","src":"dictionary:highest common factor#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “For 12 and 18 it is 6.”","opts":["highest common factor","empty set","partitioning"],"after":"highest common factor: The biggest whole number that divides exactly into two or more numbers. Short name: HCF."},"level":6},"word-improper-fraction":{"id":"word-improper-fraction","kind":"word","src":"dictionary:improper fraction#def","title":"improper fraction","body":"A fraction whose top number is bigger than its bottom number — worth more than one whole. Also called top-heavy. For example: 7/4 = 1 3/4.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"word-integer":{"id":"word-integer","kind":"word","src":"dictionary:integer#def","title":"integer","body":"A whole number, or a whole number below zero: …, −2, −1, 0, 1, 2, … For example: −6, 0 and 25 all are; 2.5 is not.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-integer":{"id":"wordq-integer","kind":"wordq","src":"dictionary:integer#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “−6, 0 and 25 all are; 2.5 is not.”","opts":["integer","term","coefficient"],"after":"integer: A whole number, or a whole number below zero: …, −2, −1, 0, 1, 2, …"},"level":6},"word-interior-angle":{"id":"word-interior-angle","kind":"word","src":"dictionary:interior angle#def","title":"interior angle","body":"A turn inside a shape, at one of its corners. For example: A regular hexagon has six of 120°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-interior-angle":{"id":"wordq-interior-angle","kind":"wordq","src":"dictionary:interior angle#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A regular hexagon has six of 120°.”","opts":["interior angle","unitary method","nth term"],"after":"interior angle: A turn inside a shape, at one of its corners."},"level":6},"word-lowest-common-multiple":{"id":"word-lowest-common-multiple","kind":"word","src":"dictionary:lowest common multiple#def","title":"lowest common multiple","body":"The smallest number that two or more numbers all divide into exactly. Short name: LCM. For example: For 4 and 6 it is 12.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"word-median":{"id":"word-median","kind":"word","src":"dictionary:median#def","title":"median","body":"The middle value once all the values are put in order. For example: 2, 3, 7, 8, 12 → 7.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-median":{"id":"wordq-median","kind":"wordq","src":"dictionary:median#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2, 3, 7, 8, 12 → 7.”","opts":["median","convert","multiple"],"after":"median: The middle value once all the values are put in order."},"level":6},"word-mixed-number":{"id":"word-mixed-number","kind":"word","src":"dictionary:mixed number#def","title":"mixed number","body":"A whole number and a fraction written together. For example: 2 1/2 means 2 wholes and a half.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-mixed-number":{"id":"wordq-mixed-number","kind":"wordq","src":"dictionary:mixed number#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2 1/2 means 2 wholes and a half.”","opts":["mixed number","kite","equilateral triangle"],"after":"mixed number: A whole number and a fraction written together."},"level":6},"word-mode":{"id":"word-mode","kind":"word","src":"dictionary:mode#def","title":"mode","body":"The value that turns up most often. For example: 3, 5, 5, 6, 5, 9 → 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-mode":{"id":"wordq-mode","kind":"wordq","src":"dictionary:mode#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3, 5, 5, 6, 5, 9 → 5.”","opts":["mode","intercept","axis"],"after":"mode: The value that turns up most often."},"level":6},"word-negative-number":{"id":"word-negative-number","kind":"word","src":"dictionary:negative number#def","title":"negative number","body":"A value below zero, written with a minus sign in front. For example: It is 3 °C and gets 5 degrees colder: now it is −2 °C.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-negative-number":{"id":"wordq-negative-number","kind":"wordq","src":"dictionary:negative number#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “It is 3 °C and gets 5 degrees colder: now it is −2 °C.”","opts":["negative number","coordinates","gram"],"after":"negative number: A value below zero, written with a minus sign in front."},"level":6},"word-parallelogram":{"id":"word-parallelogram","kind":"word","src":"dictionary:parallelogram#def","title":"parallelogram","body":"A four-sided shape whose opposite sides are parallel and equal. For example: Base 8 cm, height 3 cm: area 24 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-parallelogram":{"id":"wordq-parallelogram","kind":"wordq","src":"dictionary:parallelogram#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Base 8 cm, height 3 cm: area 24 cm².”","opts":["parallelogram","term","mixed number"],"after":"parallelogram: A four-sided shape whose opposite sides are parallel and equal."},"level":6},"word-perpendicular-height":{"id":"word-perpendicular-height","kind":"word","src":"dictionary:perpendicular height#def","title":"perpendicular height","body":"The distance straight up from the base to the top, at right angles to the base. For example: Base 6, height 4: triangle area = ½ × 6 × 4 = 12.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-perpendicular-height":{"id":"wordq-perpendicular-height","kind":"wordq","src":"dictionary:perpendicular height#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Base 6, height 4: triangle area = ½ × 6 × 4 = 12.”","opts":["perpendicular height","expression","cube"],"after":"perpendicular height: The distance straight up from the base to the top, at right angles to the base."},"level":6},"word-prime-factorisation":{"id":"word-prime-factorisation","kind":"word","src":"dictionary:prime factorisation#def","title":"prime factorisation","body":"Writing a number as a multiplication of primes only. For example: 60 = 2 × 2 × 3 × 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"word-regular":{"id":"word-regular","kind":"word","src":"dictionary:regular#def","title":"regular","body":"Having every side the same length and every angle the same size. For example: A square: 4 equal sides, 4 angles of 90°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-regular":{"id":"wordq-regular","kind":"wordq","src":"dictionary:regular#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A square: 4 equal sides, 4 angles of 90°.”","opts":["regular","outcome","Venn diagram"],"after":"regular: Having every side the same length and every angle the same size."},"level":6},"word-square-root":{"id":"word-square-root","kind":"word","src":"dictionary:square root#def","title":"square root","body":"The number which, multiplied by itself, gives the one you started with. Sign: √. For example: √81 = 9, because 9 × 9 = 81.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-square-root":{"id":"wordq-square-root","kind":"wordq","src":"dictionary:square root#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “√81 = 9, because 9 × 9 = 81.”","opts":["square root","acute angle","sample space"],"after":"square root: The number which, multiplied by itself, gives the one you started with. Sign: √."},"level":6},"word-tessellation":{"id":"word-tessellation","kind":"word","src":"dictionary:tessellation#def","title":"tessellation","body":"A pattern of shapes that fit together with no gaps and no overlaps. For example: Squares on a chessboard: 4 meet at each corner, 4 × 90° = 360°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":6},"wordq-tessellation":{"id":"wordq-tessellation","kind":"wordq","src":"dictionary:tessellation#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Squares on a chessboard: 4 meet at each corner, 4 × 90° = 360°.”","opts":["tessellation","commutative","rounding"],"after":"tessellation: A pattern of shapes that fit together with no gaps and no overlaps."},"level":6},"formula-area-square":{"id":"formula-area-square","kind":"formula","src":"formula:area-square","title":"Area of a square","body":"A = s × s = s². s rows of s squares: s², “s squared”.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a square: A square with 9 cm sides.","opts":["81","82","80"],"after":"A = 9 × 9 · = 81 cm²"},"level":6},"formula-why-area-square-0":{"id":"formula-why-area-square-0","kind":"formula-why","src":"formula:area-square#why0","title":"Why A = s × s = s²","body":"A square is a rectangle whose length and width happen to be the same, so the rectangle rule l × w becomes s × s.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-why-area-square-1":{"id":"formula-why-area-square-1","kind":"formula-why","src":"formula:area-square#why1","title":"Why A = s × s = s²","body":"That is why s × s is called “s squared”: it is how many unit squares tile a square with side s. 7² = 49 means a 7 by 7 square holds 49 little squares.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-story-area-square":{"id":"formula-story-area-square","kind":"formula-story","src":"formula:area-square#story","badge":{"id":"story","label":"A story"},"title":"The patchwork rug","body":"Mira is sewing a square rug out of patches, 8 patches along each side. — with Mira and Nova.","art":"art/s-room.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-try-area-square":{"id":"formula-try-area-square","kind":"formula-try","src":"formula:area-square#gen0","title":"Area of a square — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a square with 20 cm sides (in cm²) = ?","opts":["400","401","399"],"after":"A = s × s = s²"},"level":6},"formula-area-triangle":{"id":"formula-area-triangle","kind":"formula","src":"formula:area-triangle","title":"Area of a triangle","body":"A = ½ × b × h. The triangle takes exactly half of each part of its rectangle.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a triangle: A triangle with base 10 cm and height 6 cm.","opts":["30","31","29"],"after":"b × h = 10 × 6 = 60 · A = 60 ÷ 2 = 30 cm²"},"level":6},"formula-why-area-triangle-0":{"id":"formula-why-area-triangle-0","kind":"formula-why","src":"formula:area-triangle#why0","title":"Why A = ½ × b × h","body":"Draw a rectangle round the triangle with the same base b and the same height h. The triangle’s top corner touches the top edge.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-why-area-triangle-1":{"id":"formula-why-area-triangle-1","kind":"formula-why","src":"formula:area-triangle#why1","title":"Why A = ½ × b × h","body":"Drop a line straight down from that corner. It cuts the rectangle into two smaller rectangles, and the triangle takes exactly half of each one. Half of each part is half of the whole: A = ½ × b × h.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-story-area-triangle":{"id":"formula-story-area-triangle","kind":"formula-story","src":"formula:area-triangle#story","badge":{"id":"story","label":"A story"},"title":"The sail","body":"Ines is sewing a triangle sail for a model boat. Its base is 40 cm and it stands 30 cm tall. — with Rafi and Ines.","art":"art/s-harbour.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-try-area-triangle":{"id":"formula-try-area-triangle","kind":"formula-try","src":"formula:area-triangle#gen0","title":"Area of a triangle — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a triangle with base 13 cm and height 8 cm (in cm²) = ?","opts":["52","53","51"],"after":"A = ½ × b × h"},"level":6},"formula-area-parallelogram":{"id":"formula-area-parallelogram","kind":"formula","src":"formula:area-parallelogram","title":"Area of a parallelogram","body":"A = b × h. Slide the end triangle across and it becomes a rectangle.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a parallelogram: A parallelogram with base 9 cm and height 4 cm.","opts":["36","37","35"],"after":"A = 9 × 4 · = 36 cm²"},"level":6},"formula-why-area-parallelogram-0":{"id":"formula-why-area-parallelogram-0","kind":"formula-why","src":"formula:area-parallelogram#why0","title":"Why A = b × h","body":"Slice a triangle off one slanted end of the parallelogram and slide it across to the other end. It fits exactly, because the two slanted sides are parallel and the same length.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-why-area-parallelogram-1":{"id":"formula-why-area-parallelogram-1","kind":"formula-why","src":"formula:area-parallelogram#why1","title":"Why A = b × h","body":"Now you have a rectangle with the same base and the same straight-up height. Nothing was added and nothing was lost, so A = b × h. The slanted side’s length is never used — only the height.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-story-area-parallelogram":{"id":"formula-story-area-parallelogram","kind":"formula-story","src":"formula:area-parallelogram#story","badge":{"id":"story","label":"A story"},"title":"The slanted flowerbed","body":"A flowerbed in the city square is a parallelogram: 7 metres along the bottom and 3 metres from bottom to top, measured straight up. — with Mira and Theo.","art":"art/s-city.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-try-area-parallelogram":{"id":"formula-try-area-parallelogram","kind":"formula-try","src":"formula:area-parallelogram#gen0","title":"Area of a parallelogram — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Area of a parallelogram with base 6 cm and height 8 cm (in cm²) = ?","opts":["48","49","47"],"after":"A = b × h"},"level":6},"formula-why-volume-prism-1":{"id":"formula-why-volume-prism-1","kind":"formula-why","src":"formula:volume-prism#why1","title":"Why V = area of end × length","body":"So the end’s area tells you how much fills one slice 1 unit thick, and the length tells you how many slices there are. V = area of the end × length. A cuboid is simply a prism with a rectangle for its end.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-try-volume-prism":{"id":"formula-try-volume-prism","kind":"formula-try","src":"formula:volume-prism#gen0","title":"Volume of a prism — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A prism’s end is a triangle, base 10 cm and height 7 cm. It is 5 cm long. Volume (in cm³)?","opts":["175","176","174"],"after":"V = area of end × length"},"level":6},"formula-why-angles-round-a-point-0":{"id":"formula-why-angles-round-a-point-0","kind":"formula-why","src":"formula:angles-round-a-point#why0","title":"Why a + b + c = 360°","body":"Turn all the way round on the spot and you face the way you started: a full turn is 360°.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-story-angles-round-a-point":{"id":"formula-story-angles-round-a-point","kind":"formula-story","src":"formula:angles-round-a-point#story","badge":{"id":"story","label":"A story"},"title":"The last slice","body":"Pip cuts a round pizza from the middle. His slice has a 100° angle at the centre and Ines’s has 140°. The rest is saved for later. — with Pip and Ines.","art":"art/s-kitchen.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-angles-in-a-triangle":{"id":"formula-angles-in-a-triangle","kind":"formula","src":"formula:angles-in-a-triangle","title":"Angles in a triangle","body":"a + b + c = 180°. Tear off the three corners: they fit together on a straight line.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Angles in a triangle: A triangle has angles of 50° and 60°.","opts":["70","71","69"],"after":"50 + 60 = 110 · 180 − 110 = 70°"},"level":6},"formula-why-angles-in-a-triangle-0":{"id":"formula-why-angles-in-a-triangle-0","kind":"formula-why","src":"formula:angles-in-a-triangle#why0","title":"Why a + b + c = 180°","body":"Tear the three corners off a paper triangle and put their points together. They always fit side by side along a straight line.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-why-angles-in-a-triangle-1":{"id":"formula-why-angles-in-a-triangle-1","kind":"formula-why","src":"formula:angles-in-a-triangle#why1","title":"Why a + b + c = 180°","body":"A straight line is 180°, so the three angles of any triangle add to 180°. Draw a line through the top corner parallel to the base and you can see why: the two new angles beside the top corner copy the two bottom corners exactly.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-story-angles-in-a-triangle":{"id":"formula-story-angles-in-a-triangle","kind":"formula-story","src":"formula:angles-in-a-triangle#story","badge":{"id":"story","label":"A story"},"title":"The bunting","body":"Dax is cutting triangle flags for the fair. The two corners along the top are 70° and 70°. What is the point at the bottom? — with Mira and Dax.","art":"art/s-fair.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-try-angles-in-a-triangle":{"id":"formula-try-angles-in-a-triangle","kind":"formula-try","src":"formula:angles-in-a-triangle#gen0","title":"Angles in a triangle — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A triangle has angles of 22° and 29°. The third angle (in °)?","opts":["129","130","128"],"after":"a + b + c = 180°"},"level":6},"formula-interior-angles":{"id":"formula-interior-angles","kind":"formula","src":"formula:interior-angles","title":"Angles inside a polygon","body":"sum = (n − 2) × 180°. From one corner, a shape with n sides splits into n − 2 triangles.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Angles inside a polygon: A pentagon (5 sides).","opts":["540","541","539"],"after":"5 − 2 = 3 triangles · 3 × 180 = 540°"},"level":6},"formula-why-interior-angles-0":{"id":"formula-why-interior-angles-0","kind":"formula-why","src":"formula:interior-angles#why0","title":"Why sum = (n − 2) × 180°","body":"Stand at one corner of a shape with n sides and draw straight lines to every corner you cannot already reach along a side. The shape splits into triangles — always n − 2 of them.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-why-interior-angles-1":{"id":"formula-why-interior-angles-1","kind":"formula-why","src":"formula:interior-angles#why1","title":"Why sum = (n − 2) × 180°","body":"Each triangle holds 180°, and together their corners fill exactly the corners of the shape. So the angles inside add to (n − 2) × 180°. A hexagon: 4 triangles, 720°.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-story-interior-angles":{"id":"formula-story-interior-angles","kind":"formula-story","src":"formula:interior-angles#story","badge":{"id":"story","label":"A story"},"title":"The hexagon tiles","body":"The palace courtyard is paved with six-sided tiles. Rafi wonders what all six corners of one tile add up to. — with Kwame and Rafi.","art":"art/s-palace.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-try-interior-angles":{"id":"formula-try-interior-angles","kind":"formula-try","src":"formula:interior-angles#gen0","title":"Angles inside a polygon — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"The angles inside a shape with 12 sides add up to how many degrees?","opts":["1800","1801","1799"],"after":"sum = (n − 2) × 180°"},"level":6},"formula-exterior-angles":{"id":"formula-exterior-angles","kind":"formula","src":"formula:exterior-angles","title":"Exterior angle of a regular polygon","body":"each = 360° ÷ n. Walk round the outside: all the turns together make one full turn.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Exterior angle of a regular polygon: A regular octagon (8 sides).","opts":["45","46","44"],"after":"360 ÷ 8 = 45° · inside: 180 − 45 = 135°"},"level":6},"formula-why-exterior-angles-0":{"id":"formula-why-exterior-angles-0","kind":"formula-why","src":"formula:exterior-angles#why0","title":"Why each = 360° ÷ n","body":"Walk all the way round the outside of a shape. At each corner you turn a little, and by the time you are back at the start you face the way you began: one full turn, 360°.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-why-exterior-angles-1":{"id":"formula-why-exterior-angles-1","kind":"formula-why","src":"formula:exterior-angles#why1","title":"Why each = 360° ÷ n","body":"In a regular shape every corner turns the same amount, so each exterior angle is 360° ÷ n. The angle inside is what is left of a straight line: 180° minus that.","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-story-exterior-angles":{"id":"formula-story-exterior-angles","kind":"formula-story","src":"formula:exterior-angles#story","badge":{"id":"story","label":"A story"},"title":"The toy robot","body":"Dax programs a toy robot to drive round a flowerbed shaped like a regular pentagon: five equal sides, five equal turns. — with Theo and Dax.","art":"art/s-garden.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":6},"formula-try-exterior-angles":{"id":"formula-try-exterior-angles","kind":"formula-try","src":"formula:exterior-angles#gen0","title":"Exterior angle of a regular polygon — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Each exterior angle of a regular shape with 6 sides (in °)?","opts":["60","61","59"],"after":"each = 360° ÷ n"},"level":6}};
